#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define GPIO_LINE_OFFSET_2 3

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line1) {
        perror("gpiod_chip_get_line (offset 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET_2);
    if (!line2) {
        perror("gpiod_chip_get_line (offset 3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line1, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (line 2)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (line 3)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 2 seconds */
    while (keep_running) {
        /* Toggle line 2 */
        ret = gpiod_line_set_value(line2, !gpiod_line_get_value(line2));
        if (ret < 0) {
            perror("gpiod_line_set_value (line 2)");
            break;
        }

        /* Toggle line 1 */
        ret = gpiod_line_set_value(line1, !gpiod_line_get_value(line1));
        if (ret < 0) {
            perror("gpiod_line_set_value (line 1)");
            break;
        }

        printf("Line 2: %s, Line 1: %s\n",
               gpiod_line_get_value(line2) ? "HIGH" : "LOW",
               gpiod_line_get_value(line1) ? "HIGH" : "LOW");
        fflush(stdout);

        /* Sleep 2 seconds, but wake early if signalled */
        for (int i = 0; i < 2 && keep_running; i++) {
            sleep(1);
        }
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return (ret < 0) ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip (gpiochip0 on Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value 0 */
    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (line 1)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (line 2)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        /* Toggle both lines */
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) perror("gpiod_line_set_value (line 1)");
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) perror("gpiod_line_set_value (line 2)");

        printf("GPIO %d = 1, GPIO %d = 1\n", GPIO_PIN_1, GPIO_PIN_2);
        fflush(stdout);

        usleep(100000); /* 0.1 s */

        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) perror("gpiod_line_set_value (line 1)");
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) perror("gpiod_line_set_value (line 2)");

        printf("GPIO %d = 0, GPIO %d = 0\n", GPIO_PIN_1, GPIO_PIN_2);
        fflush(stdout);
    }

    /* Clean up: release lines and close chip */
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW (0) */
    ret = gpiod_line_request_output(line, "gpio_test", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to LOW (0).\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    while (running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid GPIO value: %d (must be 0 or 1)\n", value);
            break;
        }

        printf("GPIO %d set to HIGH (%d).\n", GPIO_LINE_OFFSET, value);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Release the line and close the chip on all exit paths */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO released. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    /*
     * Config: single-shot, AIN0 vs GND, +/-4.096V, 128 SPS, continuous.
     * Bits: 0x8000 (start single), 0x4000 (AIN0), 0x0200 (4.096V),
     * 0x0080 (128 SPS), 0x0000 (no comparator).
     */
    if (i2c_write16(fd, ADS1115_REG_CONFIG, 0x8000 | 0x4000 | 0x0200 | 0x0080) < 0) {
        perror("i2c_write16 config");
        goto cleanup;
    }

    while (running) {
        uint16_t raw;
        if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
            perror("i2c_read16 conversion");
            goto cleanup;
        }
        printf("ADC Value: %u\n", raw);
        fflush(stdout);
        usleep(500000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MLX90614_ADDR 0x5a
#define I2C_BUS "/dev/i2c-1"

static int fd = -1;

static void cleanup(void) {
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
}

int main(void) {
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MLX90614_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90614 reading started. Press Ctrl+C to exit.\n");

    while (1) {
        uint8_t cmd = 0x20;
        if (write(fd, &cmd, 1) != 1) {
            fprintf(stderr, "Error writing to MLX90614: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        uint8_t buf[3];
        ssize_t n = read(fd, buf, 3);
        if (n != 3) {
            fprintf(stderr, "Error reading from MLX90614: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        printf("Ta: %u.%u C, Tb: %u.%u C\n",
               (buf[0] & 0x0F) << 8 | buf[1],
               (buf[0] >> 4) & 0x0F,
               (buf[2] & 0x0F) << 8 | buf[3],
               (buf[2] >> 4) & 0x0F);

        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

