#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty = (rand() % (PWM_RANGE + 1));
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
            break;
        }
        printf("GPIO %d PWM duty cycle: %d\n", PWM_PIN, duty);
        fflush(stdout);
        time_sleep(0.5);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define CHIP_NAME   "gpiochip0"
#define POLL_MS     60000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int set_output(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int set_input(struct gpiod_line *line) {
    if (gpiod_line_request_input(line, "hc-sr04") < 0) {
        perror("gpiod_line_request_input");
        return -1;
    }
    return 0;
}

static long measure_pulse(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec t0, t1;
    long elapsed;

    /* 10 us trigger pulse */
    if (set_output(trig, 1) < 0) return -1;
    usleep(10);
    if (set_output(trig, 0) < 0) return -1;

    /* Wait for echo rising edge (timeout ~1 ms) */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        long ts = (t1.tv_sec - t0.tv_sec) * 1000000L +
                 (t1.tv_nsec - t0.tv_nsec) / 1000L;
        if (ts > 1000) {
            fprintf(stderr, "HC-SR04: timeout waiting for echo rising\n");
            return -1;
        }
    }

    /* Measure echo high duration */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        long ts = (t1.tv_sec - t0.tv_sec) * 1000000L +
                 (t1.tv_nsec - t0.tv_nsec) / 1000L;
        if (ts > 1000) {
            fprintf(stderr, "HC-SR04: timeout waiting for echo falling\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &t1);
    elapsed = (t1.tv_sec - t0.tv_sec) * 1000000L +
              (t1.tv_nsec - t0.tv_nsec) / 1000L;
    return elapsed;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (set_output(trig, 0) < 0) goto cleanup;
    if (set_input(echo) < 0) goto cleanup;

    printf("HC-SR04 ready. Trigger=GPIO%d, Echo=GPIO%d. Ctrl+C to exit.\n",
           TRIGGER_PIN, ECHO_PIN);
    fflush(stdout);

    while (running) {
        long v = measure_pulse(trig, echo);
        if (v < 0) {
            fprintf(stderr, "HC-SR04 measurement failed; retrying in 60 s.\n");
            sleep(60);
            continue;
        }
        printf("Distance: %ld us\n", v);
        fflush(stdout);
        sleep(60);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONSUMER_NAME "digital_output"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value HIGH */
    ret = gpiod_line_request_output(line, CONSUMER_NAME, 1);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set HIGH\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main loop: toggle state every second until interrupted */
    while (keep_running) {
        sleep(1);

        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        /* Toggle state */
        current_value = !current_value;
        ret = gpiod_line_set_value(line, current_value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set %s\n", GPIO_LINE_OFFSET, current_value ? "LOW" : "HIGH");
        fflush(stdout);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

