        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line 3)");
        goto cleanup;
    }

    /* Main loop: toggle both lines, report state, sleep 5 s */
    while (keep_running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);

        if (v1 < 0 || v2 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        /* Toggle both lines */
        gpiod_line_set_value(line1, !v1);
        gpiod_line_set_value(line2, !v2);

