#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"

#define SI7021_MEAS_TEMP_HOLD   0xE3
#define SI7021_MEAS_TEMP_NOHOLD 0xE5
#define SI7021_MEAS_RH_HOLD     0xE7
#define SI7021_MEAS_RH_NOHOLD   0xE9
#define SI7021_MEAS_PWR_DOWN    0xFE

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int si7021_init(int fd) {
    if (i2c_write(fd, SI7021_MEAS_PWR_DOWN) < 0) return -1;
    return 0;
}

static int si7021_read_temp_h(int fd, float *temp) {
    if (i2c_write(fd, SI7021_MEAS_TEMP_HOLD) < 0) return -1;
    usleep(15000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

static int si7021_read_temp_nh(int fd, float *temp) {
    if (i2c_write(fd, SI7021_MEAS_TEMP_NOHOLD) < 0) return -1;
    usleep(15000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

static int si7021_read_rh(int fd, float *rh) {
    if (i2c_write(fd, SI7021_MEAS_RH_HOLD) < 0) return -1;
    usleep(15000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *rh = (125.0f * raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f) *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (si7021_init(fd) < 0) {
        fprintf(stderr, "SI7021 not responding at 0x%02X\n", SI7021_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SI7021 ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp, rh;
        int ok = 0;

        if (si7021_read_temp_h(fd, &temp) == 0) {
            printf("Temperature (HOLD): %.2f C\n", temp);
            ok = 1;
        }
        if (si7021_read_temp_nh(fd, &temp) == 0) {
            printf("Temperature (NOHOLD): %.2f C\n", temp);
            ok = 1;
        }
        if (si7021_read_rh(fd, &rh) == 0) {
            printf("Humidity: %.2f %%\n", rh);
            ok = 1;
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nExiting.\n");
    if (close(fd) < 0) {
        perror("close");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

static int i2c_fd = -1;

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_ads1115(int fd, int16_t *raw_value) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }

    usleep(10000);

    uint16_t conv_result;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &conv_result) < 0) {
        return -1;
    }

    *raw_value = (int16_t)conv_result;
    return 0;
}

int main(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        int16_t raw_value;
        if (read_ads1115(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Error reading ADS1115 at address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
            cleanup();
            return 1;
        }
        printf("Reading %d: %d\n", i + 1, raw_value);
        sleep(1);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
