#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define GPIO_LINE_OFFSET_2 3
#define POLL_INTERVAL_SEC 0.5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line1) {
        perror("gpiod_chip_get_line(offset 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET_2);
    if (!line2) {
        perror("gpiod_chip_get_line(offset 3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line1, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line 2)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line2, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line 3)");
        goto cleanup;
    }

    /* Main loop: toggle both lines, print state, sleep */
    while (keep_running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error reading GPIO values (v1=%d, v2=%d)\n", v1, v2);
            break;
        }

        /* Toggle both lines */
        gpiod_line_set_value(line1, !v1);
        gpiod_line_set_value(line2, !v2);

        printf("GPIO %d: %d, GPIO %d: %d\n",
               GPIO_LINE_OFFSET, v1, GPIO_LINE_OFFSET_2, v2);
        fflush(stdout);

        /* Sleep 0.5 s, but wake early if signalled */
        for (int i = 0; i < 5 && keep_running; i++) {
            sleep(1);
        }
    }

cleanup:
    /* Release lines and close chip on every exit path */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

