#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define MAX_DISTANCE 400.0

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec start, end;
    long long duration_ns;
    float distance;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }

    /* Wait for echo rising edge (timeout ~100 ms) */
    int timeout = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (timeout++ > 100000) {
            fprintf(stderr, "Error: echo not responding (timeout)\n");
            return -1;
        }
        usleep(1);
    }
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high during wait\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Wait for echo falling edge (timeout ~100 ms) */
    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (timeout++ > 100000) {
            fprintf(stderr, "Error: echo stuck high (timeout)\n");
            return -1;
        }
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    duration_ns = (end.tv_sec - start.tv_sec) * 1000000000LL +
                  (end.tv_nsec - start.tv_nsec);

    distance = (duration_ns / 1000000000.0) * 34300.0 / 2.0;

    if (distance < 2.0 || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f out of range\n", distance);
        return -1;
    }

    return (int)distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        int distance = measure_distance(trig, echo);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error: failed to measure distance\n");
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

