static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    int pins[3] = GPIO_PINS;
    int i;
    int ret;

    for (i = 0; i < 3; i++) lines[i] = NULL;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get and request each line as output, initial value 0 */
    for (i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d\n", pins[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], CONSUMER, 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %d: %s\n",
                    pins[i], strerror(-ret));
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < 3; i++) {
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d: %s\n",
