#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE_1 2
#define GPIO_LINE_2 3
#define CONSUMER "digital_output"

static volatile sig_atomic_t stop = 0;

static void handle_signal(int sig) {
    (void)sig;
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        perror("gpiod_chip_get_line(line1)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        perror("gpiod_chip_get_line(line2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("GPIO %d and GPIO %d initialized as outputs.\n", GPIO_LINE_1, GPIO_LINE_2);
    printf("Running 3 cycles...\n");

    for (int i = 0; i < 3 && !stop; i++) {
        /* Set line 1 HIGH, line 2 LOW */
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line1)");
            goto cleanup;
        }
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line2)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d=HIGH, GPIO %d=LOW\n", i + 1, GPIO_LINE_1, GPIO_LINE_2);

        /* Sleep 1 s between cycles */
        sleep(1);

        /* Set line 1 LOW, line 2 HIGH */
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line1)");
            goto cleanup;
        }
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line2)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d=LOW, GPIO %d=HIGH\n", i + 1, GPIO_LINE_1, GPIO_LINE_2);

        sleep(1);
    }

    if (stop) {
        printf("\nInterrupted by signal. Exiting.\n");
    }

    /* Final state: both lines LOW */
    ret = gpiod_line_set_value(line1, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value(line1) final");
    }
    ret = gpiod_line_set_value(line2, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value(line2) final");
    }

    printf("GPIO %d and GPIO %d released.\n", GPIO_LINE_1, GPIO_LINE_2);
    return EXIT_SUCCESS;

cleanup:
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

