    int data[5] = {0, 0, 0, 0, 0};
    int i, j;

    /* Start signal: pull low for >=1 ms, then high for 20-40 us */
    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) return -1;
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    /* Switch to input */
    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    /* Wait for device to pull low (response) */
    int timeout = 0;
    while (gpiod_line_get_value(line) == 1) {
        if (stop) return -1;
        if (++timeout > 100) return -1;
        usleep(1);
    }
    timeout = 0;
    while (gpiod_line_get_value(line) == 0) {
        if (stop) return -1;
        if (++timeout > 100) return -1;
        usleep(1);
    }
    timeout = 0;
    while (gpiod_line_get_value(line) == 1) {
        if (stop) return -1;
        if (++timeout > 100) return -1;
        usleep(1);
    }

    /* Read 40 bits */
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            timeout = 0;
            while (gpiod_line_get_value(line) == 0) {
                if (stop) return -1;
                if (++timeout > 100) return -1;
                usleep(1);
            }
            timeout = 0;
            while (gpiod_line_get_value(line) == 1) {
                if (stop) return -1;
                if (++timeout > 100) return -1;
                usleep(1);
            }
            /* High pulse duration determines bit value: long = 1, short = 0 */
            if (timeout > 40) {
                data[i] |= (1 << (7 - j));
            }
        }
    }

    /* Checksum */
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -2;
    }

    /* DHT11 modes: humidity-only (0x7080), temp-only (0x7180), both (0x7280) */
    if (data[0] == 0x70 || data[0] == 0x71 || data[0] == 0x72) {
        return 0;
    }
    return -3;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    ret = read_dht11(line);
    if (ret == 0) {
        printf("DHT11: OK\n");
    } else if (ret == -1) {
        printf("DHT11: device not responding\n");
    } else if (ret == -2) {
        printf("DHT11: checksum error\n");
    } else {
        printf("DHT11: invalid data (mode error)\n");
    }

    printf("GPIO %d state: %s\n", DHT11_PIN, ret == 0 ? "OK" : "ERROR");

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

