#define NUM_PINS 5
static const unsigned int pins[NUM_PINS] = {4, 17, 18, 22, 27};

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    /* Open the gpiochip that exposes BCM pins on the Pi (gpiochip0). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line as an output, initially low. */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "digital_output", 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %u\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %u: HIGH\n", pins[i]);
        }
        fflush(stdout);
        usleep(50000); /* 0.05 s */

        for (i = 0; i < NUM_PINS; i++) {
            ret = gpiod_line_set_value(lines[i], 0);
            if (ret < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %u\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %u: LOW\n", pins[i]);
        }
        fflush(stdout);
        usleep(50000);
    }

    printf("\nExiting cleanly.\n");

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return (running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

