#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define STEP_DELAY_US 150000  /* 0.15 s */

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

static int install_signal(int signo) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(signo, &sa, NULL);
}

int main(void) {
    int pins[3] = { PWM_PIN_1, PWM_PIN_2, PWM_PIN_3 };
    int rc = EXIT_SUCCESS;

    if (install_signal(SIGINT) != 0 || install_signal(SIGTERM) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM pin %d\n", pins[i]);
            rc = EXIT_FAILURE;
            goto cleanup;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed for BCM pin %d\n", pins[i]);
            rc = EXIT_FAILURE;
            goto cleanup;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed for BCM pin %d\n", pins[i]);
            rc = EXIT_FAILURE;
            goto cleanup;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioPWM failed for BCM pin %d\n", pins[i]);
            rc = EXIT_FAILURE;
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            if (gpioPWM(pins[i], 500) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for BCM pin %d\n", pins[i]);
                rc = EXIT_FAILURE;
                goto cleanup;
            }
            printf("BCM pin %d: PWM duty cycle = 500\n", pins[i]);
        }
        fflush(stdout);
        gpioDelay(STEP_DELAY_US);
    }

cleanup:
    for (int i = 0; i < 3; i++) {
        gpioPWM(pins[i], 0);
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
    return rc;
}

