#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <signal.h>

#define BAUD_RATE 9600
#define READ_BUF_SIZE 256

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_serial(int fd) {
    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        return -1;
    }

    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1; /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_fd = open("/dev/ttyS0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (g_fd < 0) {
        fprintf(stderr, "open(/dev/ttyS0) failed: %s\n", strerror(errno));
        return 1;
    }

    if (setup_serial(g_fd) != 0) {
        close(g_fd);
        g_fd = -1;
        return 1;
    }

    printf("Serial port initialized. Waiting for device...\n");

    char buf[READ_BUF_SIZE];
    ssize_t n;
    while (g_running) {
        n = read(g_fd, buf, sizeof(buf) - 1);
        if (n > 0) {
            buf[n] = '\0';
            printf("Received: \"%s\"\n", buf);
        } else if (n == 0) {
            /* No data available; loop and check g_running */
        } else {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                fprintf(stderr, "read error: %s\n", strerror(errno));
                break;
            }
        }
    }

    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
