    if (ret < 0) {
        perror("gpiod_line_request_output(line 3)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 0.1 s */
    while (keep_running) {
        int v1 = 1;
        int v2 = 1;

        ret = gpiod_line_set_value(line1, v1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 2)");
            break;
