#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty) {
    if (duty < 0 || duty > 1000000) {
        fprintf(stderr, "Error: duty cycle %d out of range (0-1000000)\n", duty);
        return -1;
    }
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    printf("PWM on pin %d set to %d\n", pin, duty);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
            if (set_pwm(pins[i], 500000) != 0) {
                running = 0;
                break;
            }
        }
        if (running) {
            sleep(5);
        }
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define HTU21D_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define MEASURE_TEMP_HOLD 0x2E83
#define MEASURE_TEMP_REPEAT 0x2E84
#define TEMP_HOLD_DELAY_MS 15
#define TEMP_REPEAT_DELAY_MS 15

static int i2c_fd = -1;

static int i2c_write_cmd(uint8_t cmd) {
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t *buf, size_t len) {
    ssize_t n = read(i2c_fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int htu21d_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int htu21d_read_temp(float *temp) {
    if (i2c_write_cmd(MEASURE_TEMP_REPEAT) < 0) return -1;
    usleep(TEMP_REPEAT_DELAY_MS * 1000);

    uint8_t buf[3];
    if (i2c_read_block(buf, 3) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = (float)raw / 16384.0f;
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    if (htu21d_init() < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        float temp;
        if (htu21d_read_temp(&temp) == 0) {
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        sleep(60);
    }

    cleanup();
    return EXIT_SUCCESS;
}

