    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line1) {
        perror("gpiod_chip_get_line(offset 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET_2);
    if (!line2) {
        perror("gpiod_chip_get_line(offset 3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line1, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line 2)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line 3)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 2 seconds, report state */
    while (keep_running) {
        /* Toggle line 2 */
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 2 HIGH)");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_LINE_OFFSET_2);
        fflush(stdout);

        /* Toggle line 1 */
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 1 HIGH)");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        /* Toggle both lines LOW */
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 1 LOW)");
            break;
        }
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 2 LOW)");
            break;
        }

        /* Sleep 2 seconds, but wake early if signalled */
        for (int i = 0; i < 2 && keep_running; i++) {
            sleep(1);
        }
    }

cleanup:
    /* Release lines and close chip on every exit path */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return (keep_running) ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0) {
        goto cleanup;
    }

    while (running) {
        uint8_t x0, x1, y0, y1, z0, z1;

        if (i2c_read_reg8(fd, ADXL345_DATAX0, &x0) < 0 ||
            i2c_read_reg8(fd, ADXL345_DATAX0 + 1, &x1) < 0 ||
            i2c_read_reg8(fd, ADXL345_DATAX0 + 2, &y0) < 0 ||
            i2c_read_reg8(fd, ADXL345_DATAX0 + 3, &y1) < 0 ||
            i2c_read_reg8(fd, ADXL345_DATAX0 + 4, &z0) < 0 ||
            i2c_read_reg8(fd, ADXL345_DATAX0 + 5, &z1) < 0) {
            goto cleanup;
        }

        int16_t x = (int16_t)((x1 << 8) | x0);
        int16_t y = (int16_t)((y1 << 8) | y0);
        int16_t z = (int16_t)((z1 << 8) | z0);

        printf("X: %6d  Y: %6d  Z: %6d\n", x, y, z);
        fflush(stdout);

        usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00);
        close(fd);
    }
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define NUM_CYCLES 50
#define DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio_test", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting %d cycles on GPIO %d (BCM)...\n", NUM_CYCLES, GPIO_LINE);
    fflush(stdout);

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }
        printf("Cycle %d: GPIO %d HIGH\n", i + 1, GPIO_LINE);
        fflush(stdout);

        usleep(DELAY_US);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }
        printf("Cycle %d: GPIO %d LOW\n", i + 1, GPIO_LINE);
        fflush(stdout);

        usleep(DELAY_US);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (!running) {
        fprintf(stderr, "\nInterrupted by signal.\n");
    }

    return (running) ? EXIT_SUCCESS : EXIT_SUCCESS;
}

