#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PINS {17, 22, 23, 24}
#define NUM_PINS 4
#define CONSUMER "dht22_reader"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

static int wait_for_line(struct gpiod_line *line, int target, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (elapsed < timeout_us) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == target) return 0;
        sleep_us(1);
        elapsed++;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, int *humidity, int *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int i, j;

    /* Start signal: pull low for >=1ms, then high */
    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) return -1;
    gpiod_line_set_value(line, 0);
    sleep_us(2000);
    gpiod_line_set_value(line, 1);
    sleep_us(30);

    /* Switch to input */
    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    /* Read 40 bits */
    for (i = 0; i < 40; i++) {
        /* Low phase */
        if (wait_for_line(line, 0, 100) < 0) return -1;
        if (wait_for_line(line, 1, 100) < 0) return -1;

        int low_us = wait_for_line(line, 0, 100);
        if (low_us < 0) return -1;

        /* High phase */
        if (wait_for_line(line, 1, 100) < 0) return -1;
        if (wait_for_line(line, 0, 100) < 0) return -1;

        int high_us = wait_for_line(line, 1, 100);
        if (high_us < 0) return -1;

        /* Determine bit: high > 40us */
        data[i / 8] <<= 1;
        if (high_us > 40) data[i / 8] |= 1;
    }

    /* Verify checksum */
    if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = (data[0] << 8) | data[1];
    *temperature = (data[2] << 8) | data[3];
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int pins[NUM_PINS] = DHT22_PINS;
    int humidity, temperature;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (read_dht22(lines[i], &humidity, &temperature) == 0) {
                printf("GPIO %d: Humidity = %d%%, Temperature = %dC\n",
                       pins[i], humidity, temperature);
                break;
            }
        }
        sleep(2);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) gpiod_line_release(lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define STEP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d (duty=%d)\n", pin, duty);
        return -1;
    }
    printf("PWM on pin %d set to %d\n", pin, duty);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[3] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            if (set_pwm(pins[i], 500) < 0) break;
        }
        if (!running) break;
        gpioDelay(STEP_DELAY_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

