#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_STATUS 0x13
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16

static int i2c_fd = -1;

static int i2c_write_byte(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(uint8_t reg, uint8_t *value) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(void) {
    uint8_t id;
    if (i2c_read_byte(TCS34725_ID, &id) != 0) {
        return -1;
    }
    if (id != 0x44 && id != 0x50 && id != 0x54 && id != 0x58) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X\n", id);
        return -1;
    }

    if (i2c_write_byte(TCS34725_ENABLE, 0x03) != 0) return -1;
    usleep(3000);

    if (i2c_write_byte(TCS34725_ATIME, 0xFF) != 0) return -1;
    if (i2c_write_byte(TCS34725_CONTROL, 0x03) != 0) return -1;

    return 0;
}

static int tcs34725_read_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t status;
    if (i2c_read_byte(TCS34725_STATUS, &status) != 0) return -1;
    if (!(status & 0x01)) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    uint8_t cdata[2], rdata[2], gdata[2], bdata[2];
    if (i2c_read_byte(TCS34725_CDATA, &cdata[0]) != 0) return -1;
    if (i2c_read_byte(TCS34725_RDATA, &rdata[0]) != 0) return -1;
    if (i2c_read_byte(TCS34725_CDATA + 1, &cdata[1]) != 0) return -1;
    if (i2c_read_byte(TCS34725_RDATA + 1, &rdata[1]) != 0) return -1;
    if (i2c_read_byte(TCS34725_CDATA + 2, &gdata[0]) != 0) return -1;
    if (i2c_read_byte(TCS34725_CDATA + 3, &gdata[1]) != 0) return -1;
    if (i2c_read_byte(TCS34725_CDATA + 4, &bdata[0]) != 0) return -1;
    if (i2c_read_byte(TCS34725_CDATA + 5, &bdata[1]) != 0) return -1;

    *clear = (cdata[1] << 8) | cdata[0];
    *red   = (rdata[1] << 8) | rdata[0];
    *green = (gdata[1] << 8) | gdata[0];
    *blue  = (bdata[1] << 8) | bdata[0];

    return 0;
}

int main(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t clear, red, green, blue;
    while (1) {
        if (tcs34725_read_data(&clear, &red, &green, &blue) == 0) {
            printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read data\n");
        }
        usleep(200000);
    }

    close(i2c_fd);
    return 0;
}

