/*
 * capture_image.c — Raspberry Pi camera capture via v4l2.
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture_image capture_image.c
 * Run:    ./capture_image
 *
 * Requires: libgpiod (for gpioset/gpioexport cleanup) and libcamera-apps.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define OUTPUT_FILE  "image.jpg"
#define WIDTH        1280
#define HEIGHT       720
#define FRAME_COUNT  1

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void cleanup_gpio(int fd)
{
    if (fd >= 0) {
        /* Attempt to release the GPIO line. */
        if (ioctl(fd, VIDIOC_STREAMOFF, &g_stream) == -1)
            perror("VIDIOC_STREAMOFF");
        if (close(fd) == -1)
            perror("close");
    }
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_streamstream ss;
    unsigned char *image_data = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto done;

    /*
     * Open the camera device.
     * On success fd is set to a non-negative value; otherwise errno is
     * set and we exit.
     */
    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", CAMERA_DEVICE, strerror(errno));
        goto done;
    }

    /*
     * Query capabilities.
     */
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto done;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", CAMERA_DEVICE);
        goto done;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", CAMERA_DEVICE);
        goto done;
    }

    /*
     * Set format: width x height, pixel format = YUV420P.
     */
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUV420;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto done;
    }

    /*
     * Request MMAP buffers.
     */
    memset(&req, 0, sizeof(req));
    req.count = FRAME_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto done;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto done;
    }

    /*
     * Query and mmap each buffer.
     */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        goto done;
    }

    image_data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (image_data == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        image_data = NULL;
        goto done;
    }

    /*
     * Enqueue the buffer.
     */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        goto done;
    }

    /*
     * Start streaming.
     */
    memset(&ss, 0, sizeof(ss));
    ss.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ss.stream = 0;

    if (ioctl(fd, VIDIOC_STREAMON, &ss) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto done;
    }

    /*
     * Capture FRAME_COUNT frames.
     */
    for (int i = 0; i < FRAME_COUNT; i++) {
        if (g_stop) {
            fprintf(stderr, "\nInterrupted by signal.\n");
            goto streamoff;
        }

        /* Dequeue a fresh buffer. */
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            goto streamoff;
        }

        /* Write the captured frame to disk. */
        fp = fopen(OUTPUT_FILE, "wb");
        if (!fp) {
            fprintf(stderr, "Error opening %s for writing: %s\n", OUTPUT_FILE, strerror(errno));
            goto streamoff;
        }

        size_t written = fwrite(image_data, 1, buf.bytesused, fp);
        if (written != buf.bytesused) {
            fprintf(stderr, "Error writing to %s: %s\n", OUTPUT_FILE, strerror(errno));
            fclose(fp);
            fp = NULL;
            goto streamoff;
        }

        if (fclose(fp) == EOF) {
            fprintf(stderr, "Error closing %s: %s\n", OUTPUT_FILE, strerror(errno));
            fp = NULL;
            goto streamoff;
        }
        fp = NULL;

        printf("Saved %s (%zu bytes)\n", OUTPUT_FILE, buf.bytesused);

        /* Re-queue the buffer so the next frame can be captured. */
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
            goto streamoff;
        }
    }

    ret = EXIT_SUCCESS;

streamoff:
    if (fp)
        fclose(fp);
    if (image_data && image_data != MAP_FAILED)
        munmap(image_data, buf.length);
    if (ioctl(fd, VIDIOC_STREAMOFF, &ss) == -1)
        perror("VIDIOC_STREAMOFF");
    cleanup_gpio(fd);

done:
    if (ret == EXIT_SUCCESS)
        printf("Done.\n");
    return ret;
}

#include <stdio.h>
