#include <signal.h>
#include <gpiod.h>

#define GPIO_22 22
#define GPIO_27 27
#define CONSUMER "gpio_test"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line22 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip that exposes BCM GPIOs on the Pi */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line22 = gpiod_chip_get_line(chip, GPIO_22);
    if (!line22) {
        perror("gpiod_chip_get_line(GPIO 22)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line(GPIO 27)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line22, CONSUMER, 0);
