#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define OLED_WIDTH  128
#define OLED_HEIGHT 64
#define I2C_BUS      "/dev/i2c-1"
#define OLED_ADDR    0x3C

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int oled_write_cmd(int fd, uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int oled_write_data(int fd, uint8_t *data, int len) {
    uint8_t buf[1 + OLED_WIDTH];
    buf[0] = 0x40;
    for (int i = 0; i < len; i++) buf[i + 1] = data[i];
    if (write(fd, buf, len + 1) != len + 1) return -1;
    return 0;
}

static int oled_init(int fd) {
    if (oled_write_cmd(fd, 0xAE) < 0) return -1;
    if (oled_write_cmd(fd, 0xD5) < 0) return -1;
    if (oled_write_cmd(fd, 0x80) < 0) return -1;
    if (oled_write_cmd(fd, 0xA8) < 0) return -1;
    if (oled_write_cmd(fd, 0x3F) < 0) return -1;
    if (oled_write_cmd(fd, 0xD3) < 0) return -1;
    if (oled_write_cmd(fd, 0x00) < 0) return -1;
    if (oled_write_cmd(fd, 0x40) < 0) return -1;
    if (oled_write_cmd(fd, 0x8D) < 0) return -1;
    if (oled_write_cmd(fd, 0x14) < 0) return -1;
    if (oled_write_cmd(fd, 0x20) < 0) return -1;
    if (oled_write_cmd(fd, 0x00) < 0) return -1;
    if (oled_write_cmd(fd, 0xA1) < 0) return -1;
    if (oled_write_cmd(fd, 0xC8) < 0) return -1;
    if (oled_write_cmd(fd, 0xDA) < 0) return -1;
    if (oled_write_cmd(fd, 0x12) < 0) return -1;
    if (oled_write_cmd(fd, 0x81) < 0) return -1;
    if (oled_write_cmd(fd, 0x7F) < 0) return -1;
    if (oled_write_cmd(fd, 0xD9) < 0) return -1;
    if (oled_write_cmd(fd, 0x22) < 0) return -1;
    if (oled_write_cmd(fd, 0xDA) < 0) return -1;
    if (oled_write_cmd(fd, 0x12) < 0) return -1;
    if (oled_write_cmd(fd, 0xDB) < 0) return -1;
    if (oled_write_cmd(fd, 0x20) < 0) return -1;
    if (oled_write_cmd(fd, 0x00) < 0) return -1;
    if (oled_write_cmd(fd, 0xA4) < 0) return -1;
    if (oled_write_cmd(fd, 0xA6) < 0) return -1;
    if (oled_write_cmd(fd, 0xAF) < 0) return -1;
    return 0;
}

static int oled_clear(int fd) {
    uint8_t buf[1 + OLED_WIDTH];
    buf[0] = 0x40;
    for (int i = 0; i < OLED_WIDTH; i++) buf[i + 1] = 0x00;
    if (write(fd, buf, OLED_WIDTH + 1) != OLED_WIDTH + 1) return -1;
    return 0;
}

static int oled_display_text(int fd, int x, int y, const char *text) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) return -1;
    uint8_t buf[1 + 6];
    buf[0] = 0x40 + (y / 8);
    for (int i = 0; i < 6 && (x + i) < OLED_WIDTH; i++) {
        buf[i + 1] = (uint8_t)text[x + i];
    }
    if (write(fd, buf, 7) != 7) return -1;
    return 0;
}

int main(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, OLED_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }
    if (oled_init(fd) < 0) {
        fprintf(stderr, "OLED init failed\n");
        close(fd);
        return 1;
    }
    if (oled_clear(fd) < 0) {
        fprintf(stderr, "OLED clear failed\n");
        close(fd);
        return 1;
    }
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        char text[16];
        snprintf(text, sizeof(text), "Hi");
        if (oled_display_text(fd, 0, 0, text) < 0) {
            fprintf(stderr, "Display write failed\n");
            break;
        }
        usleep(100000);
    }
    oled_clear(fd);
    oled_write_cmd(fd, 0xAE);
    close(fd);
    return 0;
}

#include <stdio.h>
