#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5
#define CONSUMER "gpio_test"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    int pins[3] = {GPIO_2, GPIO_3, GPIO_5};
    int values[3] = {0, 0, 0};
    int ret = EXIT_FAILURE;

    for (int i = 0; i < 3; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, values[i]) < 0) {
