#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define TIMEOUT_PIN 24

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *timeout = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    timeout = gpiod_chip_get_line(chip, TIMEOUT_PIN);
    if (!trig || !echo || !timeout) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_input(timeout, "hc-sr04-timeout") < 0) {
        perror("gpiod_line_request_input(timeout)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig,1)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig,0)");
            break;
        }

        struct timespec ts_start, ts_now;
        clock_gettime(CLOCK_MONOTONIC, &ts_start);

        while (running) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 1) break;
            clock_gettime(CLOCK_MONOTONIC, &ts_now);
            long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                              (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
            if (elapsed_us > 200000) {
                fprintf(stderr, "Timeout waiting for echo high\n");
                goto cleanup;
            }
            usleep(100);
        }

        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long echo_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                      (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;

        if (gpiod_line_set_value(timeout, 1) < 0) {
            perror("gpiod_line_set_value(timeout,1)");
            break;
        }

        while (running) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 0) break;
            clock_gettime(CLOCK_MONOTONIC, &ts_now);
            long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                              (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
            if (elapsed_us > 200000) {
                fprintf(stderr, "Timeout waiting for echo low\n");
                goto cleanup;
            }
            usleep(100);
        }

        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long echo_end_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                          (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;

        long distance_mm = (echo_end_us - echo_us) / 2;
        printf("Distance: %ld mm\n", distance_mm);

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (timeout) gpiod_line_release(timeout);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 18
#define NUM_LEDS 1
#define DELAY_US 10000  /* 0.01 seconds */

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int colour = 0x00FF00;  /* Green */

    while (running) {
        for (int i = 0; i < NUM_LEDS; i++) {
            if (gpioWrite(LED_PIN, colour) != 0) {
                fprintf(stderr, "Failed to write to GPIO %d\n", LED_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        gpioDelay(DELAY_US);
    }

    /* Turn off LEDs before exiting */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

