#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define NUM_PINS 8
static const unsigned int pins[NUM_PINS] = {1, 4, 5, 6, 21, 22, 23, 24};

static volatile sig_atomic_t stop = 0;

static void handle_signal(int sig) {
    (void)sig;
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "digital_output", 0) < 0) {
            fprintf(stderr, "Failed to request output on GPIO %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO %u\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO %u: %s\n", pins[i], val ? "HIGH" : "LOW");
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

/*
 * capture_image.c - Raspberry Pi camera capture via linux-v4l2
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture_image capture_image.c
 * Run:    ./capture_image
 *
 * Requires: libgpiod (for gpio-vchiq support) and a Raspberry Pi camera
 *           module connected to the CSI ribbon cable.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME      "/dev/video0"
#define WIDTH            640
#define HEIGHT           480
#define IMAGE_FILE       "image.jpg"
#define CAPTURE_DELAY_US 50000   /* 0.05 s */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    void *buffer = NULL;
    struct v4l2_buffer buf;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_capability cap;
    struct v4l2_format fmt_out;
    enum v4l2_buf_type type;
    unsigned int i;
    unsigned long n_buffers;
    unsigned long size;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Open the device --- */
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Query capabilities --- */
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    /* --- Set format (4:2:2, 8-bit per channel) --- */
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUV422;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Query and request buffers --- */
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    n_buffers = req.count;
    size = req.length;

    if (n_buffers < 1) {
        fprintf(stderr, "Insufficient buffer memory (%lu)\n", n_buffers);
        goto cleanup;
    }

    /* --- Map buffers into user space --- */
    buffer = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd,
                  req.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Query current format (optional) --- */
    memset(&fmt_out, 0, sizeof(fmt_out));
    fmt_out.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt_out.fmt.index = 0;

    if (xioctl(fd, VIDIOC_G_FMT, &fmt_out) < 0) {
        fprintf(stderr, "VIDIOC_G_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fmt_out.fmt.pix.pixelformat != V4L2_PIX_FMT_YUV422) {
        fprintf(stderr, "Warning: device returned pixel format 0x%08x (expected 0x%08x)\n",
                fmt_out.fmt.pix.pixelformat, V4L2_PIX_FMT_YUV422);
    }

    /* --- Start streaming --- */
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Capturing %dx%d images at %d Hz (press Ctrl+C to stop)...\n",
           WIDTH, HEIGHT, 1000000 / CAPTURE_DELAY_US);

    /* --- Main capture loop --- */
    while (g_running) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* --- Wait for a frame to become available --- */
        while (g_running) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;

            if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                if (errno == EAGAIN) {
                    usleep(10000);
                    continue;
                }
                fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
                goto cleanup;
            }

            break;
        }

        /* --- Save the captured frame --- */
        fp = fopen(IMAGE_FILE, "wb");
        if (!fp) {
            fprintf(stderr, "Error opening %s: %s\n", IMAGE_FILE, strerror(errno));
            goto cleanup;
        }

        size_t written = fwrite(buffer, 1, buf.bytesused, fp);
        if (written != buf.bytesused) {
            fprintf(stderr, "Error writing to %s: %s\n", IMAGE_FILE, strerror(errno));
            fclose(fp);
            goto cleanup;
        }

        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing %s: %s\n", IMAGE_FILE, strerror(errno));
            goto cleanup;
        }

        printf("Saved %s (%u bytes)\n", IMAGE_FILE, buf.bytesused);

        /* --- Dequeue the frame --- */
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        if (type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            xioctl(fd, VIDIOC_STREAMOFF, &type);
        }
        if (munmap(buffer, size) < 0) {
            fprintf(stderr, "munmap failed: %s\n", strerror(errno));
        }
    }
    if (fp) {
        fclose(fp);
    }
    return ret;
}

