        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

