#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define HD44780_ADDR 0x40
#define HD44780_EN 0x04
#define HD44780_RW 0x02
#define HD44780_RS 0x01
#define HD44780_D4 0x10
#define HD44780_D5 0x20
#define HD44780_D6 0x40
#define HD44780_D7 0x80

static volatile sig_atomic_t running = 1;
static int fd = -1;

void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

void hd44780_write_nibble(int fd, unsigned char nibble) {
    unsigned char data = (HD44780_D7 & nibble) | HD44780_D6 | HD44780_D5 | HD44780_D4;
    if (write(fd, &data, 1) != 1) {
        perror("hd44780_write_nibble");
    }
}

void hd44780_send_byte(int fd, unsigned char byte) {
    hd44780_write_nibble(fd, byte & 0xF0);
    hd44780_write_nibble(fd, (byte << 4) & 0xF0);
}

void hd44780_send_command(int fd, unsigned char cmd) {
    hd44780_send_byte(fd, cmd | HD44780_EN | HD44780_RW);
}

void hd44780_send_data(int fd, unsigned char data) {
    hd44780_send_byte(fd, data | HD44780_RS);
}

void hd44780_clear(int fd) {
    hd44780_send_command(fd, 0x01);
}

void hd44780_set_cursor(int fd, int col, int row) {
    int offset = (row == 0) ? 0 : 0x40;
    hd44780_send_command(fd, 0x80 | (col + offset));
}

void hd44780_print(int fd, const char *str) {
    while (*str) {
        hd44780_send_data(fd, (unsigned char)*str++);
    }
}

void cleanup(void) {
    if (fd >= 0) {
        hd44780_send_command(fd, 0x01);
        usleep(2000);
        close(fd);
        fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sig;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HD44780_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    hd44780_clear(fd);
    hd44780_set_cursor(fd, 0, 0);
    hd44780_print(fd, "Hello, HD44780!");

    while (running) {
        sleep(10);
        hd44780_clear(fd);
        hd44780_set_cursor(fd, 0, 0);
        hd44780_print(fd, "Reading: 123");
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_GYRO_SENS 0x11
#define MPU6050_ACCEL_SENS 0x1D
#define MPU6050_WHO_AM_I 0x75

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    uint8_t whoami;
    if (i2c_read_burst(fd, MPU6050_WHO_AM_I, &whoami, 1) < 0) return -1;
    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x68\n", whoami);
        return -1;
    }
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, MPU6050_SMPLRT_DIV, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_GYRO_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_GYRO_SENS, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_ACCEL_SENS, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x01) < 0) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU6050 init failed\n");
        close(fd);
        return 1;
    }
    for (int i = 0; i < 100 && running; i++) {
        int16_t ax, ay, az;
        if (read_accel(fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Read failed at iteration %d\n", i);
            break;
        }
        printf("Accel: X=%6d, Y=%6d, Z=%6d\n", ax, ay, az);
        fflush(stdout);
        usleep(10000);
    }
    if (!running) {
        fprintf(stderr, "\nInterrupted by signal\n");
    }
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 14
#define GPIO_LINE_OFFSET_2 15
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line14 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line14) {
        perror("gpiod_chip_get_line(14)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET_2);
    if (!line15) {
        perror("gpiod_chip_get_line(15)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line14, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(14)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line15, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(15)");
        goto cleanup;
    }

    /* Main loop: toggle both lines, report state, sleep 5 s */
    while (keep_running) {
        int val = 0;
        int val2 = 0;

        val = gpiod_line_get_value(line14);
        if (val < 0) {
            perror("gpiod_line_get_value(14)");
            break;
        }

        val2 = gpiod_line_get_value(line15);
        if (val2 < 0) {
            perror("gpiod_line_get_value(15)");
            break;
        }

        printf("GPIO 14: %d, GPIO 15: %d\n", val, val2);
        fflush(stdout);

        /* Toggle both lines */
        ret = gpiod_line_set_value(line14, !val);
        if (ret < 0) {
            perror("gpiod_line_set_value(14)");
            break;
        }

        ret = gpiod_line_set_value(line15, !val2);
        if (ret < 0) {
            perror("gpiod_line_set_value(15)");
            break;
        }

        /* Sleep 5 s, but wake early if signalled */
        for (int i = 0; i < 50 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line14) {
        gpiod_line_release(line14);
    }
    if (line15) {
        gpiod_line_release(line15);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return (keep_running) ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define READ_INTERVAL_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int *value) {
    int data;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        data = gpioRead(0);
        if (data >= 0) {
            *value = data;
            return 0;
        }
        fprintf(stderr, "Error reading GPIO pin: %s (attempt %d/%d)\n",
                strerror(errno), retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(100000);
    }
    return -1;
}

static int publish_data(MQTTClient client, const char *topic, int data) {
    char payload[32];
    int rc;

    if (snprintf(payload, sizeof(payload), "%d", data) >= (int)sizeof(payload)) {
        fprintf(stderr, "Payload too large\n");
        return -1;
    }

    rc = MQTTClient_publishMessage(client, topic, (int)strlen(topic), payload, 0, 0);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT publish failed: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    MQTTClient client;
    int rc;
    int data;
    struct timespec sleep_time = {0, READ_INTERVAL_US * 1000};

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (MQTTClient_create(&client, MQTT_HOST, "test", MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClient_create failed\n");
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    rc = MQTTClient_subscribe(client, MQTT_TOPIC, 0);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT subscribe failed: %s\n", MQTTClient_strerror(rc));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    printf("Publishing sensor data to %s every 10ms. Press Ctrl+C to exit.\n", MQTT_TOPIC);

    while (running) {
        if (read_sensor_data(&data) == 0) {
            if (publish_data(client, MQTT_TOPIC, data) != 0) {
                fprintf(stderr, "Failed to publish data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }
        nanosleep(&sleep_time, NULL);
    }

    printf("\nShutting down...\n");
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
    return 0;
}

