        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d is %s\n", GPIO_LINE, val ? "HIGH" : "LOW");
        fflush(stdout);

        /* Sleep 5 seconds, but wake early if signaled */
        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define TIMEOUT_PIN 27

#define TRIGGER_PULSE_US 10
#define TIMEOUT_US       30000
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_output(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int set_input(struct gpiod_line *line) {
    if (gpiod_line_request_input(line, "hc-sr04") < 0) {
        perror("gpiod_line_request_input");
        return -1;
    }
    return 0;
}

static int read_timeout(struct gpiod_line *line, int timeout_us) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val == 0) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long diff_us = (now.tv_sec - start.tv_sec) * 1000000L +
                       (now.tv_nsec - start.tv_nsec) / 1000L;
        if (diff_us > timeout_us) return 1;
    }
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (set_output(trig, 0) < 0) return -1;
    usleep(5);
    if (set_output(trig, 1) < 0) return -1;
    usleep(TRIGGER_PULSE_US);
    if (set_output(trig, 0) < 0) return -1;

    int timeout = 0;
    while (1) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val == 1) break;
        if (++timeout > TIMEOUT_US) return 1;
        usleep(10);
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    timeout = 0;
    while (1) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val == 0) break;
        clock_gettime(CLOCK_MONOTONIC, &end);
        long diff_us = (end.tv_sec - start.tv_sec) * 1000000L +
                       (end.tv_nsec - start.tv_nsec) / 1000L;
        if (diff_us > TIMEOUT_US) return 1;
        if (++timeout > TIMEOUT_US) return 1;
        usleep(10);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    long diff_us = (end.tv_sec - start.tv_sec) * 1000000L +
                   (end.tv_nsec - start.tv_nsec) / 1000L;

    float distance = (float)diff_us / 2.0f;
    if (distance < 2.0f || distance > 400.0f) return 1;
    return (int)distance;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *timeout = gpiod_chip_get_line(chip, TIMEOUT_PIN);
    if (!trig || !echo || !timeout) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (set_output(timeout, 1) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        int d = measure_distance(trig, echo);
        if (d < 0) {
            fprintf(stderr, "Measurement failed or timeout.\n");
        } else {
            printf("Distance: %d mm\n", d);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    set_output(timeout, 0);
    gpiod_chip_close(chip);
    return 0;
}

