#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/readings"
#define SENSOR_READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static MQTTClient client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int publish_sensor_data(const char *topic, const char *payload) {
    int rc;
    rc = MQTTClient_connect(client, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", MQTTClient_strerror(rc));
        return -1;
    }

    rc = MQTTClient_publishMessage(client, topic, (int)strlen(payload), payload, 0, 0);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", MQTTClient_strerror(rc));
        MQTTClient_disconnect(client, 1000);
        return -1;
    }

    printf("Published: %s\n", payload);
    return 0;
}

int main(void) {
    int rc;
    char payload[128];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    rc = MQTTClient_create(&client, MQTT_HOST, "sensor_publisher", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error creating MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return 1;
    }

    while (running) {
        int sensor_value = gpioRead(0);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO pin: %s\n", pigpio_error(sensor_value));
            sleep(1);
            continue;
        }

        snprintf(payload, sizeof(payload), "%d", sensor_value);
        if (publish_sensor_data(MQTT_TOPIC, payload) != 0) {
            fprintf(stderr, "Failed to publish sensor data\n");
        }

        sleep(SENSOR_READ_INTERVAL_SEC);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
