#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define STEP_US 500000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty = (running) ? 500 : 0;
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "gpioPWM failed on GPIO %d\n", PWM_PIN);
            break;
        }
        printf("GPIO %d PWM: %d\n", PWM_PIN, duty);
        fflush(stdout);
        gpioDelay(STEP_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define CONSUMER     "hcsr04"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int set_output(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int set_input(struct gpiod_line *line) {
    if (gpiod_line_request_input(line, CONSUMER) < 0) {
        perror("gpiod_line_request_input");
        return -1;
    }
    return 0;
}

static long measure_pulse(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec t0, t1;
    long elapsed_ns;

    /* 10 us trigger pulse */
    if (set_output(trig, 1) < 0) return -1;
    usleep(10);
    if (set_output(trig, 0) < 0) return -1;

    /* Wait for echo rising edge (timeout ~1 ms) */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        long elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000L +
                          (t1.tv_nsec - t0.tv_nsec) / 1000L;
        if (elapsed_us > 1000) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &t0);

    /* Wait for echo falling edge (timeout ~1 ms) */
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        long elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000L +
                          (t1.tv_nsec - t0.tv_nsec) / 1000L;
        if (elapsed_us > 1000) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);

    elapsed_ns = (t1.tv_sec - t0.tv_sec) * 1000000000L +
                 (t1.tv_nsec - t0.tv_nsec);
    return elapsed_ns;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (set_output(trig, 0) < 0) goto cleanup;
    if (set_input(echo) < 0) goto cleanup;

    while (running) {
        long ns = measure_pulse(trig, echo);
        if (ns < 0) {
            fprintf(stderr, "Measurement failed; continuing\n");
            usleep(200000);
            continue;
        }

        /* distance = (ns / 2) / 58700  (cm) */
        printf("Distance: %ld cm\n", ns / 2 / 1000000000L * 58700L / 2);
        fflush(stdout);
        usleep(200000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
