    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/readings"
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define SENSOR_READ_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static int mqtt_connected = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int gpio_pin, int *value) {
    int count = 0;
    int timeout_ms = SENSOR_READ_TIMEOUT_MS;

    while (count < 1 && timeout_ms > 0) {
        int level = gpioRead(gpio_pin);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
            return -1;
        }
        if (level == 0) {
            *value = 0;
            return 0;
        }
        if (level == 1) {
            *value = 1;
            return 0;
        }
        count++;
        gpioDelay(1000);
        timeout_ms -= 1000;
    }

    fprintf(stderr, "Sensor on GPIO %d did not respond within %d ms\n", gpio_pin, SENSOR_READ_TIMEOUT_MS);
    return -1;
}

static int publish_sensor_data(const char *topic, int value) {
    char payload[32];
    int len = snprintf(payload, sizeof(payload), "%d", value);
    if (len < 0 || len >= (int)sizeof(payload)) {
        fprintf(stderr, "Payload formatting error\n");
        return -1;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (uint16_t)len;
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT publish failed: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int gpio_pin = 17;
    if (gpioSetMode(gpio_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pin);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    int rc = MQTTClient_create(&client, MQTT_HOST, "sensor_publisher", MQTTCLIENT_PERSISTENCE_NONE, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT client creation failed: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClient_connect(client, 120);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    mqtt_connected = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_value = 0;
        if (read_sensor_data(gpio_pin, &sensor_value) != 0) {
            fprintf(stderr, "Sensor read failed; skipping publish\n");
        } else {
            if (publish_sensor_data(MQTT_TOPIC, sensor_value) != 0) {
                fprintf(stderr, "Failed to publish sensor data\n");
            }
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (mqtt_connected) {
        MQTTClient_disconnect(client, 1000);
    }
    MQTTClient_destroy(&client);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_KEEPALIVE 60
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128_SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128_SPS | ADS1115_CONFIG_CQUE_NONE)
#define NUM_READINGS 10

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int pigpio_initialized = 0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_ads1115(int handle, int16_t *value) {
    char cfg[2];
    char reg[1] = {ADS1115_REG_CONFIG};
    char conv[1] = {ADS1115_REG_CONVERSION};
    char buf[2];

    cfg[0] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    cfg[1] = ADS1115_CONFIG_DEFAULT & 0xFF;

    if (i2cWriteI2CBlockData(handle, reg, cfg, 2) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }

    usleep(10000);

    if (i2cReadI2CBlockData(handle, conv, buf, 2) < 0) {
        fprintf(stderr, "Error reading conversion from ADS1115\n");
        return -1;
    }

    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

void publish_reading(int16_t value) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", value);
    mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
}

int main() {
    int handle;
    int16_t value;
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating MQTT client\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_PORT, MQTT_KEEPALIVE);
    mosquitto_loop_start(mosq);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int i = 0; i < NUM_READINGS; i++) {
        if (!running) break;
        if (read_ads1115(handle, &value) == 0) {
            publish_reading(value);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        usleep(100000);
    }

    mosquitto_loop_stop(mosq, false);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    if (pigpio_initialized) {
        i2cClose(handle);
        gpioTerminate();
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define CONSUMER "gpio_test"
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip that exposes BCM GPIOs on the Pi */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line18, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    while (running) {
        int v17 = gpiod_line_get_value(line17);
        int v18 = gpiod_line_get_value(line18);

        if (v17 < 0 || v18 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", v17, v18);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    /* Turn outputs off and release the lines */
    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line18, 0);
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

cleanup:
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

#include <stdio.h>
