#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_17 17
#define GPIO_23 23

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line23 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the gpiochip (gpiochip0 on Pi 3/4, gpiochip4 on Pi 5) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip4");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        perror("gpiod_chip_get_line(23)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line23, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output(23)");
        goto cleanup;
    }

    /* Set both lines high */
    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("gpiod_line_set_value(17)");
        goto cleanup;
    }

    if (gpiod_line_set_value(line23, 1) < 0) {
        perror("gpiod_line_set_value(23)");
        goto cleanup;
    }

    printf("GPIO 17 and GPIO 23 set HIGH\n");
    fflush(stdout);

    /* Install signal handlers for clean exit on Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* Sleep until signal received */
    while (running) {
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line23) {
        gpiod_line_release(line23);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

