#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define BAUD_RATE 9600
#define READ_BUF_SIZE 256

static volatile sig_atomic_t running = 1;
static int serial_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_serial(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    serial_fd = setup_serial("/dev/ttyS0");
    if (serial_fd < 0) {
        return 1;
    }

    char read_buf[READ_BUF_SIZE];
    ssize_t bytes_read;

    while (running) {
        bytes_read = read(serial_fd, read_buf, sizeof(read_buf) - 1);
        if (bytes_read > 0) {
            read_buf[bytes_read] = '\0';
            printf("Received: %s\n", read_buf);
        } else if (bytes_read < 0 && errno != EAGAIN && errno != EWOULDBLOCK) {
            fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            break;
        }
        usleep(10000);
    }

    if (serial_fd >= 0) {
        close(serial_fd);
        serial_fd = -1;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static int fd = -1;

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_mpu6050(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t h, l;
    if (i2c_read_reg8(fd, ACCEL_XOUT_H, &h) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_XOUT_H + 1, &l) < 0) return -1;
    *ax = (int16_t)((h << 8) | l);
    if (i2c_read_reg8(fd, ACCEL_XOUT_H + 2, &h) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_XOUT_H + 3, &l) < 0) return -1;
    *ay = (int16_t)((h << 8) | l);
    if (i2c_read_reg8(fd, ACCEL_XOUT_H + 4, &h) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_XOUT_H + 5, &l) < 0) return -1;
    *az = (int16_t)((h << 8) | l);
    return 0;
}

int main(void) {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(100000);
    int16_t ax, ay, az;
    while (1) {
        if (read_mpu6050(fd, &ax, &ay, &az) == 0) {
            printf("Accel X: %6d, Y: %6d, Z: %6d\n", ax, ay, az);
        } else {
            fprintf(stderr, "Error reading MPU6050: %s\n", strerror(errno));
        }
        usleep(100000);
    }
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CALIB_26 0xE1

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

struct bmp280_calib {
    uint16_t dig_T1; int16_t dig_T2, dig_T3;
    uint16_t dig_P1; int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
};

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    ssize_t n = read(fd, buf, len);
    return (n == (ssize_t)len) ? 0 : -1;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_read_calibration(int fd, struct bmp280_calib *c) {
    uint8_t d1[24], d2[7];
    if (i2c_read_reg(fd, BMP280_REG_CALIB_00, d1, 24) < 0) return -1;
    if (i2c_read_reg(fd, BMP280_REG_CALIB_26, d2, 7) < 0) return -1;
    c->dig_T1 = (uint16_t)(d1[0] | (d1[1] << 8));
    c->dig_T2 = (int16_t)(d1[2] | (d1[3] << 8));
    c->dig_T3 = (int16_t)(d1[4] | (d1[5] << 8));
    c->dig_P1 = (uint16_t)(d1[6] | (d1[7] << 8));
    c->dig_P2 = (int16_t)(d1[8] | (d1[9] << 8));
    c->dig_P3 = (int16_t)(d1[10] | (d1[11] << 8));
    c->dig_P4 = (int16_t)(d1[12] | (d1[13] << 8));
    c->dig_P5 = (int16_t)(d1[14] | (d1[15] << 8));
    c->dig_P6 = (int16_t)(d1[16] | (d1[17] << 8));
    c->dig_P7 = (int16_t)(d1[18] | (d1[19] << 8));
    c->dig_P8 = (int16_t)(d1[20] | (d1[21] << 8));
    c->dig_P9 = (int16_t)(d1[22] | (d1[23] << 8));
    return 0;
}

static int bmp280_init(int fd, struct bmp280_calib *c) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: cannot read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: wrong chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: reset write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    if (bmp280_read_calibration(fd, c) < 0) {
        fprintf(stderr, "Error: calibration read failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: config write failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: ctrl_meas write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read(int fd, struct bmp280_calib *c, float *temp, float *press) {
    uint8_t d[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, d, 6) < 0) return -1;
    int32_t raw_p = (d[0] << 12) | (d[1] << 4) | (d[2] >> 4);
    int32_t raw_t = (d[3] << 12) | (d[4] << 4) | (d[5] >> 4);
    double v1 = ((double)raw_t / 16384.0 - (double)c->dig_T1 / 1024.0) * c->dig_T2;
    double v2 = ((double)raw_t / 131072.0 - (double)c->dig_T1 / 8192.0) *
                ((double)raw_t / 131072.0 - (double)c->dig_T1 / 8192.0) * c->dig_T3;
    double t = v1 + v2;
    *temp = (float)(t + 25.0);
    double v3 = (double)raw_p / 262144.0 - (double)c->dig_P1 / 8192.0;
    double v4 = v3 * v3 * c->dig_P2 / 32768.0;
    double v5 = v3 * c->dig_P3 / 32768.0;
    double v6 = v4 + v5 + c->dig_P4 / 16.0;
    double v7 = v6 + c->dig_P5 / 16384.0;
    double v8 = v7 + c->dig_P6 / 1048576.0;
    double v9 = v8 + c->dig_P7 / 67108864.0;
    double p = (double)raw_p / 262144.0 - (double)c->dig_P1 / 8192.0;
    p = (p - v6) * 6250.0 / 4096.0;
    p = p * (1.0 + v7 / 4096.0);
    p = p * (1.0 + v8 / 32768.0);
    p = p * (1.0 + v9 / 16777216.0);
    *press = (float)p;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (bmp280_init(fd, NULL) < 0) {
        fprintf(stderr, "Error: BMP280 init failed\n");
        close(fd);
        return 1;
    }
    struct bmp280_calib cal;
    float temp, press;
    while (g_running) {
        if (bmp280_read(fd, &cal, &temp, &press) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp, press);
        } else {
            fprintf(stderr, "Error: read failed\n");
        }
        for (int i = 0; i < 50 && g_running; i++) usleep(100000);
    }
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 500;
    if (gpioPWM(PWM_PIN, duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM duty cycle set to %d\n", duty);

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PINS {5, 6, 13}
#define NUM_PINS 3

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int pins[NUM_PINS] = GPIO_PINS;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio_test", 0) < 0) {
            fprintf(stderr, "Failed to request output for GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO %d: %d\n", pins[i], val);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_KEEPALIVE 60

static volatile sig_atomic_t running = 1;
static MQTTClient client;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void cleanup(void) {
    if (client) {
        MQTTClient_disconnect(client, MQTT_KEEPALIVE);
        MQTTClient_destroy(&client);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    MQTTClient_create(&client, MQTT_HOST, MQTT_CLIENT_ID, MQTTClient_PersistenceNone, NULL);
    if (!client) {
        fprintf(stderr, "MQTT client creation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = MQTT_KEEPALIVE;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(client, &conn_opts) != MQTT_ERR_SUCCESS) {
        fprintf(stderr, "MQTT connect failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (MQTTClient_subscribe(client, MQTT_TOPIC, 0) != MQTT_ERR_SUCCESS) {
        fprintf(stderr, "MQTT subscribe failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_value = gpioRead(0);
        if (sensor_value < 0) {
            fprintf(stderr, "gpioRead failed\n");
            break;
        }

        char payload[32];
        int len = snprintf(payload, sizeof(payload), "%d", sensor_value);
        if (len < 0 || (size_t)len >= sizeof(payload)) {
            fprintf(stderr, "Payload formatting failed\n");
            break;
        }

        MQTTClient_publishMessage(client, MQTT_TOPIC, len, payload, 0, 0);
        printf("Published: %s\n", payload);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PINS {2,3,18,23,24}
#define NUM_PINS 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[NUM_PINS] = PWM_PINS;
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], 255) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        printf("GPIO %d: PWM duty cycle 128 (range 0-255, freq 1000 Hz)\n", pins[i]);
    }

    while (running) {
        gpioDelay(100000);
    }

    gpioPWM(pins[0], 0);
    gpioPWM(pins[1], 0);
    gpioPWM(pins[2], 0);
    gpioPWM(pins[3], 0);
    gpioPWM(pins[4], 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM 128 on GPIO 17, 22, 27\n");
        fflush(stdout);
        gpioDelay(50000); /* 0.05 s */
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

/*
 * capture_image.c - Capture images from Raspberry Pi camera module using
 * linux-v4l2.  Saves each capture to a file named "image_YYYYMMDD_HHMMSS.jpg".
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture_image capture_image.c
 * Run:    ./capture_image
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAPTURE_INTERVAL_SEC  1
#define MAX_FILENAME_LEN      256
#define MAX_PATH_LEN          4096

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int format_filename(char *buf, size_t buflen, const char *prefix)
{
    time_t rawtime;
    struct tm tm_info;

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(buf, buflen, "%Y%m%d_%H%M%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed: buffer too small\n");
        return -1;
    }

    if (snprintf(buf + strlen(buf), buflen - strlen(buf), ".%s", prefix) >= buflen) {
        fprintf(stderr, "Filename too long\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    const char *device_name = "/dev/video0";
    int fd = open(device_name, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", device_name, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", device_name);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (format_filename(NULL, 0, "jpg") != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    char filename[MAX_FILENAME_LEN];
    if (format_filename(filename, sizeof(filename), "jpg") != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Capturing image to %s\n", filename);

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = type;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = type;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        buffer = NULL;
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_eo_try_state state = V4L2_EO_TRY_ON;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
