        bytes_read += buf.len;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto stream_off;
        }
    }

    if (stop_requested) {
        goto stream_off;
    }

    if (bytes_read != image_size) {
        fprintf(stderr, "Incomplete capture: %zu of %zu bytes\n", bytes_read, image_size);
        goto stream_off;
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", IMAGE_FILE, strerror(errno));
        goto stream_off;
    }

    size_t written = fwrite(image, 1, image_size, fp);
    if (written != image_size) {
        fprintf(stderr, "Failed to write all data to %s\n", IMAGE_FILE);
        goto stream_off;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close %s: %s\n", IMAGE_FILE, strerror(errno));
        goto stream_off;
    }
    fp = NULL;

    printf("Image saved to %s (%zu bytes)\n", IMAGE_FILE, image_size);
    ret = EXIT_SUCCESS;

stream_off:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        }
    }

cleanup:
    if (image) free(image);
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define GPIO_LINE_OFFSET_2 3

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line1) {
        perror("gpiod_chip_get_line(offset 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET_2);
    if (!line2) {
        perror("gpiod_chip_get_line(offset 3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line1, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line 2)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line 3)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 0.5 s until interrupted */
    while (keep_running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);

        if (v1 < 0 || v2 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n",
               GPIO_LINE_OFFSET, v1, GPIO_LINE_OFFSET_2, v2);
        fflush(stdout);

        /* Toggle both lines */
        ret = gpiod_line_set_value(line1, !v1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 2)");
            break;
        }

        ret = gpiod_line_set_value(line2, !v2);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 3)");
            break;
        }

        sleep(0.5);
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return (keep_running) ? EXIT_FAILURE : EXIT_SUCCESS;
}

