    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define CONSUMER "dht22-reader"

static volatile sig_atomic_t stop_flag = 0;

static void handle_signal(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int read_dht22(struct gpiod_line *line, int *humidity, int *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int last_state = 1;
    int bit_idx = 0;
    int timeout = 0;

    /* Start signal: pull low for >= 1 ms, then high for 20-40 us */
    if (gpiod_line_request_output(line, CONSUMER, 1) < 0) return -1;
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    /* Switch to input; DHT22 pulls low to signal request */
    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    /* Wait for DHT22 to pull low (response start) */
    while (gpiod_line_get_value(line) == 1) {
        if (stop_flag) return -1;
        usleep(1);
        timeout++;
        if (timeout > 100) return -1;
    }

    /* Wait for DHT22 to pull high (response end) */
    timeout = 0;
    while (gpiod_line_get_value(line) == 0) {
        if (stop_flag) return -1;
        usleep(1);
        timeout++;
        if (timeout > 100) return -1;
    }
    timeout = 0;
    while (gpiod_line_get_value(line) == 1) {
        if (stop_flag) return -1;
        usleep(1);
        timeout++;
        if (timeout > 100) return -1;
    }

    /* Read 40 bits */
    for (int i = 0; i < 40; i++) {
        timeout = 0;
        while (gpiod_line_get_value(line) == last_state) {
            if (stop_flag) return -1;
            usleep(1);
            timeout++;
            if (timeout > 100) return -1;
        }
        last_state = gpiod_line_get_value(line);

        /* Ignore first 16 transitions (header) */
        if (i >= 16 && i % 2 == 0) {
            data[bit_idx / 8] <<= 1;
            if (timeout > 40) data[bit_idx / 8] |= 1;
            bit_idx++;
            if (bit_idx % 8 == 0) {
                if (data[bit_idx / 8] == 1) {
                    /* End of transmission */
                    break;
                }
            }
        }
    }

    if (bit_idx < 40) return -1;

    /* Validate checksum */
    if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) != data[4]) {
        return -1;
    }

    *humidity = (data[0] << 8) | data[1];
    *temperature = (data[2] << 8) | data[3];
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int humidity, temperature;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (read_dht22(line, &humidity, &temperature) == 0) {
        printf("Humidity: %d%%, Temperature: %dC\n", humidity, temperature);
    } else {
        printf("Failed to read DHT22 data\n");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25
#define CONSUMER "gpio_test"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4];
    int pins[4] = {GPIO_17, GPIO_23, GPIO_24, GPIO_25};
    int values[4] = {0, 0, 0, 0};
    int ret;

    for (int i = 0; i < 4; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], CONSUMER, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output: %s\n", pins[i], strerror(-ret));
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < 4; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Failed to read GPIO %d: %s\n", pins[i], strerror(-values[i]));
                goto cleanup;
            }
        }
        printf("GPIO 17: %d, GPIO 23: %d, GPIO 24: %d, GPIO 25: %d\n",
               values[0], values[1], values[2], values[3]);
        fflush(stdout);
        sleep(10);
    }

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return running ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MCP3008_CHANNEL 0
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/data"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = serRead(1, (char *)tx, 3);
    if (ret != 3) {
        fprintf(stderr, "serRead failed (ret=%d)\n", ret);
        return -1;
    }

    ret = serRead(1, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "serRead (data) failed (ret=%d)\n", ret);
        return -1;
    }

    /* rx[0] is a dummy echo; rx[1] low nibble + rx[2] are the 10-bit result */
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

static int publish_reading(int channel, int adc_value) {
    char payload[64];
    snprintf(payload, sizeof(payload), "channel=%d,adc=%d", channel, adc_value);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC,
                               (int)strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "mosquitto_publish failed: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "mosquitto_new failed\n");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, 1883, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "mosquitto_connect failed: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "mosquitto_loop_start failed: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    while (running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "Failed to read MCP3008\n");
        } else {
            if (publish_reading(MCP3008_CHANNEL, adc) != 0) {
                fprintf(stderr, "Failed to publish reading\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpioTerminate();
    mosquitto_lib_cleanup();

    return 0;
}

/*
 * capture_image.c - Capture an image from the Raspberry Pi camera module
 * using the linux-v4l2 API.
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture_image capture_image.c
 * Run:    ./capture_image
 *
 * Requires: libgphoto2-2 (libgphoto2-port) with v4l2 support, or
 *           libcamera-apps (modern camera stack).
 *
 * If libcamera-apps is available, this program uses it.  Otherwise it
 * falls back to a minimal v4l2 capture loop.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEFAULT_WIDTH  640
#define DEFAULT_HEIGHT 480
#define DEFAULT_TIMEOUT_MS  5000

static int g_width  = DEFAULT_WIDTH;
static int g_height = DEFAULT_HEIGHT;
static int g_timeout_ms = DEFAULT_TIMEOUT_MS;

/*
 * libcamera-apps provides a user-friendly command-line interface to the
 * Raspberry Pi camera.  If it is available, we delegate to it.
 */
static int have_libcamera(void)
{
    int fd = open("/sys/class/camera/libcamera/camera_id", O_RDONLY);
    if (fd < 0) {
        /* Not fatal: some older Pi models do not have the libcamera bridge. */
        return 0;
    }
    char buf[32];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    close(fd);
    if (n <= 0) {
        return 0;
    }
    buf[n] = '\0';
    return (strcmp(buf, "cmos-3555") == 0 ||
            strcmp(buf, "imx219")  == 0 ||
            strcmp(buf, "imx477")  == 0 ||
            strcmp(buf, "imx708")  == 0);
}

static int capture_with_libcamera(const char *filename)
{
    char cmd[512];
    snprintf(cmd, sizeof(cmd),
             "libcamera-still -o %s -w %d -h %d --timeout 1000",
             filename, g_width, g_height);
    int rc = system(cmd);
    if (rc == -1) {
        fprintf(stderr, "system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(rc) || WEXITSTATUS(rc) != 0) {
        fprintf(stderr, "libcamera-still failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

/*
 * Minimal v4l2 capture loop.
 *
 * NOTE: this is a fallback only.  The Raspberry Pi camera is a CSI-2
 * device and requires a full userspace driver stack (libcamera, v4l2-ctl,
 * v4l2-daemon).  A bare v4l2 ioctl-only capture is not guaranteed to
 * work on all Pi models and is not recommended for production.
 */
static int capture_with_v4l2(const char *filename)
{
    int fd = open(filename, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", filename);
        close(fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", filename);
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = g_width;
    fmt.fmt.pix.height = g_height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                        MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap: %s\n", strerror(errno));
        buffer = NULL;
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    /*
     * Capture loop.  We use a 1-second timeout so we can bail out if the
     * camera is unresponsive.
     */
    for (int elapsed = 0; elapsed < g_timeout_ms; elapsed += 100) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                usleep(10000);
                continue;
            }
            fprintf(stderr, "VIDIOC_DQBUF: %s\n", strerror(errno));
            goto cleanup;
        }

        /*
         * libcamera-still writes JPEG.  We write raw YUV data here so the
         * output is a raw YUV file that can be converted later.
         *
         * For a production application, use libcamera-still or a proper
         * v4l2-app-based capture.
         */
        size_t to_write = buf.bytesused;
        ssize_t w = write(fd, buffer, to_write);
        if (w < 0) {
            fprintf(stderr, "write: %s\n", strerror(errno));
            goto cleanup;
        }
        if ((size_t)w != to_write) {
            fprintf(stderr, "short write: %zd of %zu\n", w, to_write);
            goto cleanup;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    fprintf(stderr, "Camera did not respond within %d ms\n", g_timeout_ms);
    goto cleanup;

cleanup:
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF: %s\n", strerror(errno));
    }
    if (munmap(buffer, buf.length) < 0) {
        fprintf(stderr, "munmap: %s\n", strerror(errno));
    }
    close(fd);
    return -1;
}

