    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line 18");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output 17");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line18, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output 18");
        goto cleanup;
    }

    for (int i = 0; i < 3 && running; i++) {
        /* Set GPIO 17 HIGH, GPIO 18 LOW */
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value 17");
            goto cleanup;
        }
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value 18");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17=HIGH, GPIO 18=LOW\n", i + 1);
        fflush(stdout);

        /* Sleep 1 s between cycles */
        sleep(1);

        /* Set GPIO 17 LOW, GPIO 18 HIGH */
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value 17");
