        }
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value 18");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17=LOW, GPIO 18=HIGH\n", i + 1);
        fflush(stdout);

        sleep(1);
    }

    /* Final state: both LOW */
    ret = gpiod_line_set_value(line17, 0);
    if (ret < 0) perror("gpiod_line_set_value 17");
    ret = gpiod_line_set_value(line18, 0);
    if (ret < 0) perror("gpiod_line_set_value 18");

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
