#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static int fd = -1;

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (write(fd, (uint8_t[]){ACCEL_XOUT_H}, 1) != 1) return -1;
    if (read(fd, buf, 6) != 6) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (1) {
        int16_t x, y, z;
        if (read_accel(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        printf("Accel: X=%d, Y=%d, Z=%d\n", x, y, z);
        usleep(100000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17
#define CONSUMER "gpio_test"
#define NUM_CYCLES 3
#define DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    int pins[3] = {GPIO_2, GPIO_3, GPIO_17};
    int i;
    int ret;

    for (i = 0; i < 3; i++) lines[i] = NULL;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line as output, initial value LOW */
    for (i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO %d\n", pins[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], CONSUMER, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                    pins[i], strerror(-ret));
            goto cleanup;
        }
    }

    printf("Starting %d cycles on GPIO %d, %d, %d. Press Ctrl+C to stop.\n",
           NUM_CYCLES, GPIO_2, GPIO_3, GPIO_17);

    for (i = 0; i < NUM_CYCLES && running; i++) {
        /* Set all three lines HIGH */
        ret = gpiod_line_set_value(lines[0], 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d: %s\n",
                    GPIO_2, strerror(-ret));
            goto cleanup;
        }
        ret = gpiod_line_set_value(lines[1], 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d: %s\n",
                    GPIO_3, strerror(-ret));
            goto cleanup;
        }
        ret = gpiod_line_set_value(lines[2], 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d: %s\n",
                    GPIO_17, strerror(-ret));
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d=HIGH, GPIO %d=HIGH, GPIO %d=HIGH\n",
               i + 1, GPIO_2, GPIO_3, GPIO_17);

        sleep(DELAY_SEC);

        /* Set all three lines LOW */
        ret = gpiod_line_set_value(lines[0], 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d: %s\n",
                    GPIO_2, strerror(-ret));
            goto cleanup;
        }
        ret = gpiod_line_set_value(lines[1], 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d: %s\n",
                    GPIO_3, strerror(-ret));
            goto cleanup;
        }
        ret = gpiod_line_set_value(lines[2], 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d: %s\n",
                    GPIO_17, strerror(-ret));
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d=LOW, GPIO %d=LOW, GPIO %d=LOW\n",
               i + 1, GPIO_2, GPIO_3, GPIO_17);

        sleep(DELAY_SEC);
    }

    if (!running) {
        printf("\nInterrupted by signal. Exiting.\n");
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    for (i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return (running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

