#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int states[] = {0, 1, 0, 1};
    for (int i = 0; i < num_pins; i++) {
        if (gpioPWM(pins[i], states[i]) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("GPIO %d PWM state: %d\n", pins[i], states[i]);
    }

    printf("PWM running on pins %d, %d, %d, %d. Press Ctrl+C to exit.\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);

    while (running) {
        gpioDelay(100000);
    }

    gpioPWM(pins[0], 0);
    gpioPWM(pins[1], 0);
    gpioPWM(pins[2], 0);
    gpioPWM(pins[3], 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define GPIO_LINE_OFFSET_2 3

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line1) {
        perror("gpiod_chip_get_line(offset 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET_2);
    if (!line2) {
        perror("gpiod_chip_get_line(offset 3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line1, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line 2)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line 3)");
        goto cleanup;
    }

    /* Main loop: toggle both lines once per second */
    while (keep_running) {
        /* Toggle line 2 */
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 2 HIGH)");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_LINE_OFFSET_2);
        fflush(stdout);

        /* Toggle line 1 */
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 1 HIGH)");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        /* Toggle both lines LOW */
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 2 LOW)");
            break;
        }
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line 1 LOW)");
            break;
        }

        sleep(1);
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return (keep_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

