        for (i = 0; i < 4; i++) {
            ret = gpiod_line_set_value(lines[i], 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO %d low: %s\n",
                        pins[i], strerror(-ret));
                goto cleanup;
            }
        }
        printf("GPIO pins set to LOW\n");
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < POLL_INTERVAL_SEC && running; s++)
            sleep(1);
    }

cleanup:
