#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>

#define W1_BUS "/sys/bus/w1/devices/28-000005e73bff/w1_slave"
#define W1_TEMP_FILE "temperature"
#define MAX_READINGS 3
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int read_temperature(const char *bus_path, float *out_temp) {
    char path[256];
    char buffer[256];
    FILE *fp;
    int fd;
    char *token;
    long raw_temp;

    snprintf(path, sizeof(path), "%s/%s", bus_path, W1_TEMP_FILE);

    fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    token = strstr(buffer, "t=");
    if (token == NULL) {
        fprintf(stderr, "Temperature data not found in file\n");
        return -1;
    }

    raw_temp = strtol(token + 2, NULL, 10);
    *out_temp = (float)raw_temp / 1000.0;

    return 0;
}

int main(void) {
    float temperature;
    int readings_taken = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    printf("Reading DS18B20 temperature every %d seconds. Press Ctrl+C to stop.\n", READ_INTERVAL_SEC);

    while (!stop_flag && readings_taken < MAX_READINGS) {
        if (read_temperature(W1_BUS, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            readings_taken++;
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds.\n", READ_INTERVAL_SEC);
        }

        if (!stop_flag && readings_taken < MAX_READINGS) {
            sleep(READ_INTERVAL_SEC);
        }
    }

    if (stop_flag) {
        printf("\nInterrupted by signal. Exiting.\n");
    }

    return (readings_taken >= MAX_READINGS) ? 0 : 1;
}

