#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define TIMEOUT_PIN 24

#define TRIGGER_VALUE 1
#define ECHO_VALUE    0
#define TIMEOUT_VALUE 0

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *timeout = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    timeout = gpiod_chip_get_line(chip, TIMEOUT_PIN);
    if (!trig || !echo || !timeout) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", TRIGGER_VALUE) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_input(timeout, "hc-sr04-timeout") < 0) {
        perror("gpiod_line_request_input(timeout)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(trig, TRIGGER_VALUE) < 0) {
            perror("gpiod_line_set_value(trig)");
            break;
        }
        usleep(10);

        if (gpiod_line_set_value(trig, ECHO_VALUE) < 0) {
            perror("gpiod_line_set_value(trig)");
            break;
        }
        usleep(10);

        struct timespec ts = {0, 10000000}; /* 10 ms */
        int val = gpiod_line_get_value(timeout);
        if (val < 0) {
            perror("gpiod_line_get_value(timeout)");
            break;
        }

        if (val == TIMEOUT_VALUE) {
            fprintf(stderr, "HC-SR04 timeout: no echo received\n");
            break;
        }

        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                break;
            }
            if (val == ECHO_VALUE) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                long long diff_ns = (end.tv_sec - start.tv_sec) * 1000000000LL +
                                    (end.tv_nsec - start.tv_nsec);
                float distance = diff_ns / 1000000000.0f * 34300.0f / 2.0f;
                printf("Distance: %.2f cm\n", distance);
                break;
            }
            usleep(100);
        }

        if (!running) break;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (timeout) gpiod_line_release(timeout);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

