#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define CONSUMER "dht22-reader"
#define MAX_RETRIES 3

static volatile sig_atomic_t stop_flag = 0;

static void handle_signal(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int wait_for_line(struct gpiod_line *line, int target, int timeout_us) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != target) {
        if (stop_flag) return -1;
        usleep(1);
        elapsed++;
        if (elapsed > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line) {
    int data[5] = {0, 0, 0, 0, 0};
    int i;

    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) return -1;
    usleep(500000);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(20000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    if (wait_for_line(line, 0, 100000) < 0) return -1;
    if (wait_for_line(line, 1, 100000) < 0) return -1;
    if (wait_for_line(line, 0, 100000) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_line(line, 1, 100000) < 0) return -1;
        if (wait_for_line(line, 0, 100000) < 0) return -1;
        int count = 0;
        while (gpiod_line_get_value(line) == 1) {
            count++;
            if (count > 100) return -1;
        }
        data[i / 8] <<= 1;
        if (count > 40) data[i / 8] |= 1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    return (data[0] << 8) | (data[1] << 4) | data[2];
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int i = 0; i < MAX_RETRIES && !stop_flag; i++) {
        int result = read_dht22(line);
        if (result >= 0) {
            printf("Cycle %d: %d\n", i + 1, result);
            ret = 0;
        } else if (result == -1) {
            fprintf(stderr, "Cycle %d: read failed (timeout or line error)\n", i + 1);
        } else {
            fprintf(stderr, "Cycle %d: read failed (invalid data)\n", i + 1);
        }
        usleep(2000000);
    }

    if (stop_flag) {
        fprintf(stderr, "\nInterrupted by signal.\n");
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

