    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(PWM_PINS[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PINS[i]);
