#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PINS {17, 18, 22, 23, 24, 25}
#define NUM_PINS 6
#define PERIOD_US 1000000  /* 1 second in microseconds */
#define DUTY_CYCLE_US 500000 /* 50% duty cycle */
#define LOOP_DELAY_US 50000  /* 0.05 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    const int pins[NUM_PINS] = PWM_PINS;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], DUTY_CYCLE_US) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int state = gpioGetPWMdutycycle(pins[i]);
            if (state < 0) {
                fprintf(stderr, "Failed to read PWM duty cycle on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: PWM duty cycle = %d us\n", pins[i], state);
        }
        fflush(stdout);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: turn off PWM on all pins */
    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

