#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_line(struct gpiod_line *line, int target, int timeout_us) {
    int elapsed = 0;
    while (elapsed < timeout_us) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == target) return 0;
        usleep(1);
        elapsed++;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line1, struct gpiod_line *line2,
                      float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int i, j;

    /* Start signal: pull low for >=1ms, then high */
    if (gpiod_line_request_output(line1, "dht22", 0) < 0) return -1;
    if (gpiod_line_request_output(line2, "dht22", 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line1, 1) < 0) return -1;
    if (gpiod_line_set_value(line2, 1) < 0) return -1;
    usleep(30);
    if (gpiod_line_set_value(line1, 0) < 0) return -1;

    /* Switch to input */
    if (gpiod_line_request_input(line1, "dht22") < 0) return -1;
    if (gpiod_line_request_input(line2, "dht22") < 0) return -1;

    /* Wait for DHT22 to pull low (response) */
    if (wait_for_line(line2, 0, 1000) < 0) return -1;
    /* Wait for DHT22 to pull high (response end) */
    if (wait_for_line(line2, 1, 1000) < 0) return -1;
    /* Wait for DHT22 to pull low (data start) */
    if (wait_for_line(line2, 0, 1000) < 0) return -1;

    /* Read 40 bits */
    for (i = 0; i < 5; i++) {
        for (j = 7; j >= 0; j--) {
            /* Wait for line1 to go high (start of bit) */
            if (wait_for_line(line1, 1, 1000) < 0) return -1;
            /* Wait for line1 to go low (end of bit) */
            if (wait_for_line(line1, 0, 1000) < 0) return -1;
            int bit = gpiod_line_get_value(line2);
            if (bit < 0) return -1;
            data[i] = (data[i] << 1) | bit;
        }
    }

    /* Checksum */
    if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) != data[4]) {
        return -2;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int i = 0; i < MAX_RETRIES && running; i++) {
        float humidity, temperature;
        int rc = read_dht22(line1, line2, &humidity, &temperature);
        if (rc == 0) {
            printf("Cycle %d: Humidity = %.1f%%, Temperature = %.1f°C\n",
                   i + 1, humidity, temperature);
            ret = 0;
            break;
        }
        if (rc == -2) {
            fprintf(stderr, "Cycle %d: Invalid DHT22 data\n", i + 1);
        } else {
            fprintf(stderr, "Cycle %d: Failed to read DHT22 (rc=%d)\n", i + 1, rc);
        }
        if (i < MAX_RETRIES - 1 && running) {
            sleep(RETRY_DELAY_SEC);
        }
    }

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

