#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define VCC_PIN 18
#define GND_PIN 27

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *vcc = NULL, *gnd = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    vcc  = gpiod_chip_get_line(chip, VCC_PIN);
    gnd  = gpiod_chip_get_line(chip, GND_PIN);
    if (!trig || !echo || !vcc || !gnd) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_output(vcc, "hc-sr04-vcc", 1) < 0) {
        perror("gpiod_line_request_output(vcc)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(gnd, "hc-sr04-gnd", 0) < 0) {
        perror("gpiod_line_request_output(gnd)");
        goto cleanup;
    }

    /* Ensure device is powered and quiet before sending a pulse */
    gpiod_line_set_value(vcc, 1);
    usleep(100000);
    gpiod_line_set_value(trig, 0);
    usleep(2000);

    /* Send 10 us trigger pulse */
    gpiod_line_set_value(trig, 1);
    usleep(10);
    gpiod_line_set_value(trig, 0);

    /* Measure echo high duration (with timeout) */
    struct timespec t0, t1;
    int val;
    long elapsed_us = 0;
    const long timeout_us = 100000; /* 100 ms */

    clock_gettime(CLOCK_MONOTONIC, &t0);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            goto cleanup;
        }
        if (val == 1) {
            clock_gettime(CLOCK_MONOTONIC, &t1);
            elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000L +
                         (t1.tv_nsec - t0.tv_nsec) / 1000L;
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &t1);
        elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000L +
                     (t1.tv_nsec - t0.tv_nsec) / 1000L;
    } while (elapsed_us < timeout_us);

    if (elapsed_us == 0) {
        fprintf(stderr, "HC-SR04: no echo received (device not responding?)\n");
        goto cleanup;
    }

    /* Calculate distance: speed of sound ~343 m/s => 0.0343 mm/us */
    float distance_mm = (float)elapsed_us * 0.0343f / 2.0f;

    printf("HC-SR04: distance = %.2f mm\n", distance_mm);

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (vcc)  gpiod_line_release(vcc);
    if (gnd)  gpiod_line_release(gnd);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

