}

struct bmp280_calib {
    uint16_t dig_T1; int16_t dig_T2, dig_T3;
    uint16_t dig_P1; int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
};

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration(int fd, struct bmp280_calib *c) {
    uint8_t buf[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB_00, buf, 24) < 0) return -1;
    c->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    c->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    c->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    c->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    c->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    c->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    c->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    c->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    c->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    c->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    c->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    c->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t g_t_fine;

static int32_t compensate_temp(int32_t adc_T, const struct bmp280_calib *c) {
    int32_t var1 = ((((adc_T >> 3) - ((int32_t)c->dig_T1 << 1))) * ((int32_t)c->dig_T2)) >> 11;
    int32_t var2 = (((((adc_T >> 4) - ((int32_t)c->dig_T1)) * ((adc_T >> 4) - ((int32_t)c->dig_T1))) >> 12) * ((int32_t)c->dig_T3)) >> 14;
    g_t_fine = var1 + var2;
    return (g_t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_press(int32_t adc_P, const struct bmp280_calib *c) {
    int64_t var1 = ((int64_t)g_t_fine) - 128000;
    int64_t var2 = var1 * var1 * (int64_t)c->dig_P6;
    var2 = var2 + ((var1 * (int64_t)c->dig_P5) << 17);
    var2 = var2 + (((int64_t)c->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)c->dig_P3) >> 8) + ((var1 * (int64_t)c->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)c->dig_P1) >> 33;
    if (var1 == 0) return 0;
    int64_t p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)c->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)c->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)c->dig_P7) << 4);
    return (uint32_t)((p >> 8) * 25) / 100;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "BMP280 not found (no ACK)\n");
        close(fd);
        return 1;
    }
    if (id != 0x60) {
        fprintf(stderr, "BMP280 ID mismatch: 0x%02X\n", id);
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Reset failed\n");
        close(fd);
        return 1;
    }
    usleep(2000);

    struct bmp280_calib cal;
    if (read_calibration(fd, &cal) < 0) {
        fprintf(stderr, "Calibration read failed\n");
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Config write failed\n");
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Ctrl_meas write failed\n");
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3 && running; i++) {
        uint8_t buf[6];
        if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, buf, 6) < 0) {
            fprintf(stderr, "Read failed at iteration %d\n", i);
            break;
        }
        int32_t adc_P = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
        int32_t adc_T = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);

        int32_t t = compensate_temp(adc_T, &cal);
        uint32_t p = compensate_press(adc_P, &cal);

        printf("Temperature: %d m°C, Pressure: %u Pa\n", t, p);
        fflush(stdout);
        usleep(2000000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4];
    int pins[4] = {GPIO_17, GPIO_22, GPIO_23, GPIO_24};
    int values[4] = {0, 1, 0, 1};
    int ret = EXIT_FAILURE;

    for (int i = 0; i < 4; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio_test", values[i]) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < 4; i++) {
        printf("GPIO %d: %s\n", pins[i], values[i] ? "HIGH" : "LOW");
    }
    printf("GPIO control complete.\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) gpiod_line_release(lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
