#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB00 0x88
#define BME280_REG_CALIB26 0xE1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: failed to read chip ID\n");
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: unexpected chip ID 0x%02X (expected 0x60)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: failed to reset device\n");
        return -1;
    }
    usleep(2000);
    uint8_t status;
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg8(fd, BME280_REG_STATUS, &status) < 0) return -1;
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if (status & 0x01) {
        fprintf(stderr, "Error: device still reset\n");
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bme280_read_calibration(int fd, uint8_t *c) {
    uint8_t buf[26];
    if (i2c_read_block(fd, BME280_REG_CALIB00, buf, 26) < 0) return -1;
    c[0] = (buf[1] << 8) | buf[0];
    c[1] = (buf[3] << 8) | buf[2];
    c[2] = (buf[5] << 8) | buf[4];
    c[3] = (buf[7] << 8) | buf[6];
    c[4] = (buf[9] << 8) | buf[8];
    c[5] = (buf[11] << 8) | buf[10];
    c[6] = (buf[13] << 8) | buf[12];
    c[7] = (buf[15] << 8) | buf[14];
    c[8] = (buf[17] << 8) | buf[16];
    c[9] = (buf[19] << 8) | buf[18];
    if (i2c_read_block(fd, BME280_REG_CALIB26, buf, 7) < 0) return -1;
    c[10] = (buf[1] << 4) | (buf[0] & 0x0F);
    c[11] = (buf[2] << 4) | (buf[3] >> 4);
    c[12] = buf[4];
    c[13] = (buf[6] << 4) | (buf[5] & 0x0F);
    c[14] = (buf[7] << 4) | (buf[8] >> 4);
    c[15] = buf[9];
    return 0;
}

static int bme280_read(int fd, const uint8_t *c, float *t, float *p, float *h) {
    uint8_t buf[8];
    if (i2c_read_block(fd, BME280_REG_DATA, buf, 8) < 0) return -1;
    int32_t adc_p = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    int32_t adc_t = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    int32_t adc_h = (buf[6] << 8) | buf[7];
    double v1 = ((double)adc_t / 16384.0 - (double)c[0] / 1024.0) * c[1];
    double v2 = ((double)adc_t / 131072.0 - (double)c[0] / 8192.0) *
                ((double)adc_t / 131072.0 - (double)c[0] / 8192.0) * c[2];
    double t_fine = v1 + v2;
    *t = (float)(t_fine / 5120.0);
    double p_var1 = (t_fine / 2.0) - 64000.0;
    double p_var2 = p_var1 * p_var1 * c[3] / 32768.0;
    p_var2 = p_var2 + p_var1 * c[4] / 26843.0;
    double p_var3 = (p_var2 / 4.0) + ((double)c[5] * 65536.0);
    p_var3 = p_var3 / 100.0;
    double p_var4 = (p_var3 * p_var3 * c[6] / 2147483648.0);
    p_var4 = p_var4 + (p_var3 * c[7] / 26843.0);
    p_var4 = (p_var4 / 2.0) + (double)c[8] / 16384.0;
    double p = (p_var4 * 100.0);
    *p = (float)p;
    double h_var1 = (t_fine - 76800.0);
    h_var1 = (double)adc_h - ((double)c[9] * 64.0 + (double)c[10] / 16384.0 * h_var1);
    h_var1 = h_var1 * (double)c[11] / 65536.0 * (1.0 + (double)c[12] / 67108864.0 * h_var1 * (1.0 + (double)c[13] / 268435456.0 * h_var1));
    *h = (float)h_var1;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }
    if (bme280_init(fd) < 0) {
        fprintf(stderr, "Error: BME280 init failed\n");
        close(fd);
        return 1;
    }
    uint8_t cal[16];
    if (bme280_read_calibration(fd, cal) < 0) {
        fprintf(stderr, "Error: calibration read failed\n");
        close(fd);
        return 1;
    }
    for (int i = 0; i < 3 && running; i++) {
        float t, p, h;
        if (bme280_read(fd, cal, &t, &p, &h) < 0) {
            fprintf(stderr, "Error: read failed\n");
            close(fd);
            return 1;
        }
        printf("Reading %d: T=%.2f C, P=%.2f hPa, H=%.2f %%\n", i + 1, t, p, h);
        sleep(5);
    }
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, "gpio_test", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to LOW\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    while (keep_running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        /* Sleep 1 second; gpiod_line_set_value is already blocking */
        sleep(1);
    }

    /* Release the line and close the chip on all exit paths */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released and chip closed.\n", GPIO_LINE_OFFSET);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define VEML7700_ADDR 0x10
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    while (running) {
        uint16_t conf = 0x0000;
        if (i2c_read_reg16(fd, 0x00, &conf) < 0) {
            fprintf(stderr, "Error reading configuration register\n");
            goto cleanup;
        }

        uint16_t data = 0;
        if (i2c_read_reg16(fd, 0x04, &data) < 0) {
            fprintf(stderr, "Error reading data register\n");
            goto cleanup;
        }

        printf("VEML7700: %u\n", data);
        fflush(stdout);

        usleep(500000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <signal.h>

#define BAUD_RATE 9600
#define READ_INTERVAL_US 100000  /* 0.1 s */
#define MAX_READ_RETRIES 10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int configure_port(int fd)
{
    struct termios tty;

    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;  /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto done;

    fd = open("/dev/ttyS0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "open(\"/dev/ttyS0\") failed: %s\n", strerror(errno));
        goto done;
    }

    if (configure_port(fd) != 0) {
        fprintf(stderr, "configure_port failed\n");
        goto cleanup;
    }

    printf("Serial port configured at %d baud. Waiting for device...\n", BAUD_RATE);
    fflush(stdout);

    while (g_running) {
        char buf[256];
        ssize_t n = read(fd, buf, sizeof(buf) - 1);

        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(READ_INTERVAL_US);
                continue;
            }
            fprintf(stderr, "read() failed: %s\n", strerror(errno));
            goto cleanup;
        }

        if (n == 0) {
            usleep(READ_INTERVAL_US);
            continue;
        }

        buf[n] = '\0';
        printf("Received: \"%s\"\n", buf);
        fflush(stdout);

        usleep(READ_INTERVAL_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
done:
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define POLL_MS     500

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int set_output(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int set_input(struct gpiod_line *line) {
    if (gpiod_line_request_input(line, "hc-sr04") < 0) {
        perror("gpiod_line_request_input");
        return -1;
    }
    return 0;
}

static int read_echo(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return val;
}

static long elapsed_us(struct timespec *start, struct timespec *end) {
    return (long)(end->tv_sec - start->tv_sec) * 1000000L +
           (end->tv_nsec - start->tv_nsec) / 1000L;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec t0, t1;
    int val;

    if (set_output(trig, 0) < 0) return -1;
    usleep(2);
    if (set_output(trig, 1) < 0) return -1;
    usleep(10);
    if (set_output(trig, 0) < 0) return -1;

    if (set_input(echo) < 0) return -1;

    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (;;) {
        val = read_echo(echo);
        if (val < 0) return -1;
        if (val == 1) break;
        clock_gettime(CLOCK_MONOTONIC, &t1);
        long e = elapsed_us(&t0, &t1);
        if (e > 500000L) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (;;) {
        val = read_echo(echo);
        if (val < 0) return -1;
        if (val == 0) break;
        clock_gettime(CLOCK_MONOTONIC, &t1);
        long e = elapsed_us(&t0, &t1);
        if (e > 500000L) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
    }

    long dur = elapsed_us(&t0, &t1);
    if (dur < 10000L || dur > 200000L) {
        fprintf(stderr, "Distance out of range: %ld us\n", dur);
        return -1;
    }
    return (int)(dur / 2000000L);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }
    if (gpiod_line_request_output(echo, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int d = measure_distance(trig, echo);
        if (d < 0) {
            fprintf(stderr, "Measurement failed; retrying next cycle.\n");
        } else {
            printf("Distance: %d mm\n", d);
        }
        usleep(POLL_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle state every 1 ms */
    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }
        printf("GPIO 8 HIGH\n");
        fflush(stdout);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }
        printf("GPIO 8 LOW\n");
        fflush(stdout);

        usleep(1000);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

