static int read_echo_pulse(struct gpiod_line *echo_line) {
    struct timespec ts_start, ts_end;
    long long duration = 0;
    int val;

    /* Wait for echo to go HIGH (start of pulse) */
    while ((val = gpiod_line_get_value(echo_line)) == 0) {
        if (!running) return -1;
        usleep(100);
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    /* Wait for echo to go LOW (end of pulse) */
    while ((val = gpiod_line_get_value(echo_line)) == 1) {
        if (!running) return -1;
        usleep(100);
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_end);

    duration = (ts_end.tv_sec - ts_start.tv_sec) * 1000000000LL +
               (ts_end.tv_nsec - ts_start.tv_nsec);

    return (int)duration;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

