        }

        int duration = read_echo_pulse(echo_line);
        if (duration < 0) {
            fprintf(stderr, "Error reading echo pulse.\n");
            goto cleanup;
        }

        /* Convert duration to distance (mm).
         * distance = (duration * 34300 cm/s) / 2 / 1000000
         * distance = duration * 0.01715 cm
         * distance = duration * 17.15 mm
         */
        double distance_mm = (double)duration * 0.01715;

        printf("Distance: %.2f mm\n", distance_mm);
        usleep(100000); /* 0.1s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 16
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 500;
    if (gpioPWM(PWM_PIN, duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM duty cycle set to %d\n", duty);

    while (running) {
        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_GDATAL 0x18
#define TCS34725_GDATAH 0x19

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), val };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Error: failed to read ID register\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Error: unexpected ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: failed to enable ALS\n");
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error: failed to set integration time\n");
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error: failed to set gain\n");
        return -1;
    }
    return 0;
}

static int tcs34725_read(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    if (i2c_read_reg16(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATAL, b) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_CDATAL, c) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }
    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "Error: TCS34725 not detected at 0x%02X\n", TCS34725_I2C_ADDR);
        close(fd);
        return 1;
    }
    while (running) {
        uint16_t r, g, b, c;
        if (tcs34725_read(fd, &r, &g, &b, &c) == 0) {
            printf("R: %5u  G: %5u  B: %5u  C: %5u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Error: I2C read failed\n");
        }
        sleep(1);
    }
    close(fd);
    return 0;
}

