    }

    printf("HC-SR04 ready: TRIG=GPIO%d, ECHO=GPIO%d, STAB=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, STABILIZE_PIN);
    printf("State: TRIG=0, ECHO=0, STAB=0\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (stab) gpiod_line_release(stab);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

