#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24
#define CONSUMER "gpio_test"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    int pins[3] = { GPIO_18, GPIO_23, GPIO_24 };
    int values[3] = { 0, 1, 0 };
    int ret = EXIT_FAILURE;

    for (int i = 0; i < 3; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, values[i]) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Failed to set GPIO %d\n", pins[i]);
                goto cleanup;
            }
        }
        printf("GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
               GPIO_18, values[0], GPIO_23, values[1], GPIO_24, values[2]);
        fflush(stdout);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int16_t ax, ay, az;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Wake the MPU6050: clear sleep bit, use internal 8 MHz oscillator */
    uint8_t buf[2] = {PWR_MGMT_1, 0x00};
    if (write(fd, buf, 2) != 2) {
        perror("write PWR_MGMT_1");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t reg = ACCEL_XOUT_H;
        if (write(fd, &reg, 1) != 1) {
            perror("write register address");
            break;
        }

        uint8_t data[6];
        if (read(fd, data, 6) != 6) {
            perror("read accelerometer data");
            break;
        }

        ax = (int16_t)((data[0] << 8) | data[1]);
        ay = (int16_t)((data[2] << 8) | data[3]);
        az = (int16_t)((data[4] << 8) | data[5]);

        printf("Accel: X=%d, Y=%d, Z=%d\n", ax, ay, az);
        fflush(stdout);

        sleep(1);
    }

    if (fd >= 0) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_SEC 0.6

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio_test", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to LOW. Press Ctrl+C to exit.\n", GPIO_LINE);
    fflush(stdout);

    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_LINE);
        fflush(stdout);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_LINE);
        fflush(stdout);

        /* Sleep for POLL_INTERVAL_SEC, but wake early on signal */
        for (int i = 0; i < 10 && running; i++) {
            usleep(600000); /* 0.6 s */
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nGPIO released. Exiting.\n");
    return EXIT_SUCCESS;
}
